/// Records the accessor `$name` of `$owner` returning `$property`
/// (`metadata::record_property_accessor`) with the `compiler-metadata`
/// feature of this crate; expands to nothing without it.
#[cfg(feature = "compiler-metadata")]
#[doc(hidden)]
#[macro_export]
macro_rules! __record_property_accessor {
    ($owner:ident, $vis:vis, $name:ident, $property:expr) => {
        $crate::metadata::record_property_accessor(
            <$owner as $crate::StaticType>::TYPE,
            ::std::any::TypeId::of::<Self>(),
            ::std::stringify!($name),
            ::std::stringify!($vis),
            $crate::Registrable::as_registered_property($property),
        )
    };
}

/// Records the accessor `$name` of `$owner` returning `$property` with the
/// `compiler-metadata` feature of this crate; expands to nothing without it.
#[cfg(not(feature = "compiler-metadata"))]
#[doc(hidden)]
#[macro_export]
macro_rules! __record_property_accessor {
    ($owner:ident, $vis:vis, $name:ident, $property:expr) => {};
}

/// Declares the accessor of a single property definition.
///
/// ```ignore
/// impl Border {
///     ferro_property!(pub fn background_property() -> StyledProperty<Option<Ref<Brush>>> {
///         FerroProperty::register::<Border, _>("Background", None)
///     });
/// }
/// ```
///
/// The property is registered the first time the accessor is called on a
/// thread. Property definitions, like the objects that use them, belong to
/// the thread that created them.
///
/// On its own the macro registers nothing until the accessor is called, so a
/// lookup by name can miss the property. Declare the properties of a type in
/// a [`ferro_properties!`] block instead, which also registers them when the
/// type is initialised.
///
/// Where an accessor cannot be written inside the block (it is generated by
/// a local macro, or declared between other items), name the type whose
/// initialisation it belongs to and list it in the block of that type:
///
/// ```ignore
/// ferro_property!(for XYFocus; pub fn left_property() -> AttachedProperty<..> { .. });
///
/// ferro_properties! { impl XYFocus, also [XYFocus::left_property] {} }
/// ```
#[macro_export]
macro_rules! ferro_property {
    // An accessor that belongs to the static initialisation of `$owner`: the
    // first call on a thread first initialises the owner (as reading a
    // static field of a class runs its static initialisation), which
    // registers the properties of the owner in declaration order, this one
    // included.
    (for $owner:ident; $(#[$meta:meta])* $vis:vis fn $name:ident() -> $ty:ty $body:block) => {
        $(#[$meta])*
        #[inline]
        $vis fn $name() -> &'static $ty {
            $crate::ferro_thread_local! {
                static CELL: ::std::cell::Cell<::std::option::Option<&'static $ty>> =
                    const { ::std::cell::Cell::new(::std::option::Option::None) };
            }
            match CELL.get() {
                ::std::option::Option::Some(property) => property,
                ::std::option::Option::None => {
                    <$owner as $crate::StaticType>::TYPE.ensure_class_init();
                    match CELL.get() {
                        ::std::option::Option::Some(property) => property,
                        // Reached while the owner is being initialised (this
                        // is the registration in declaration order), or for
                        // an owner whose runtime type has no initialisation.
                        ::std::option::Option::None => {
                            let property: &'static $ty = $body;
                            CELL.set(::std::option::Option::Some(property));
                            $crate::__record_property_accessor!($owner, $vis, $name, property);
                            property
                        }
                    }
                }
            }
        }
    };

    ($(#[$meta:meta])* $vis:vis fn $name:ident() -> $ty:ty $body:block) => {
        $(#[$meta])*
        #[inline]
        $vis fn $name() -> &'static $ty {
            $crate::ferro_thread_local! {
                static CELL: ::std::cell::Cell<::std::option::Option<&'static $ty>> =
                    const { ::std::cell::Cell::new(::std::option::Option::None) };
            }
            match CELL.get() {
                ::std::option::Option::Some(property) => property,
                ::std::option::Option::None => {
                    let property: &'static $ty = $body;
                    CELL.set(::std::option::Option::Some(property));
                    property
                }
            }
        }
    };
}

/// Declares the property definitions of a type: the accessors, as
/// [`ferro_property!`] declares them one by one, and their registration as
/// part of the static initialisation of the type.
///
/// ```ignore
/// ferro_properties! {
///     impl Border {
///         /// Defines the `Background` property.
///         pub fn background_property() -> StyledProperty<Option<Ref<Brush>>> {
///             FerroProperty::register::<Border, _>("Background", None)
///         }
///
///         /// Defines the `Child` property (declared by another class).
///         pub fn child_property() -> StyledProperty<Option<Ref<Control>>> {
///             Decorator::child_property().add_owner::<Border>()
///         }
///     }
/// }
/// ```
///
/// All the properties are registered, in declaration order (the order of the
/// static field initialisers of the managed class), when the type is
/// initialised on a thread: when the first instance of the class or of a
/// class deriving from it is created, when one of the accessors is first
/// called, or when the property registry is asked about the type, whichever
/// comes first. A lookup by name therefore finds every property, whether or
/// not its accessor was called and whether or not an instance exists. After
/// that an accessor is a thread-local read, exactly as with
/// [`ferro_property!`].
///
/// The owner is a class ([`ferro_class!`](crate::ferro_class)) or a type
/// declared with [`ferro_static_type!`](crate::ferro_static_type).
///
/// Existing `ferro_property!(..);` invocations can be wrapped in the block
/// unchanged:
///
/// ```ignore
/// ferro_properties! { impl Border {
///     ferro_property!(pub fn background_property() -> StyledProperty<Option<Ref<Brush>>> {
///         FerroProperty::register::<Border, _>("Background", None)
///     });
/// } }
/// ```
///
/// A type has one such block. Properties of the type that are declared
/// elsewhere are named by it: `impl Owner, also [path, ..] { .. }` registers
/// the properties of the block first and then calls the listed functions in
/// order. A listed function is either
///
/// * the registration function of another block of accessors, declared with
///   `ferro_properties! { impl Owner, fn name { .. } }` (an upstream partial
///   class in a second file): `also [InputElement::register_gesture_properties]`;
/// * or a single accessor declared with `ferro_property!(for Owner; ..)`
///   (accessors generated by a local macro or interleaved with other items):
///   `also [XYFocus::left_property, XYFocus::right_property]`.
#[macro_export]
macro_rules! ferro_properties {
    (@accessors $owner:ident { $( $(#[$meta:meta])* $vis:vis fn $name:ident() -> $ty:ty $body:block )* }) => {
        $(
            $crate::ferro_property!(for $owner; $(#[$meta])* $vis fn $name() -> $ty $body);
        )*
    };

    // The main block, wrapping `ferro_property!(..);` invocations. The
    // accessors are declared through the macro name written at the call
    // site, so the block works with the import the file already has.
    (
        impl $owner:ident $(, also [$($more:path),* $(,)?])? {
            $( $macro_:ident ! ( $(#[$meta:meta])* $vis:vis fn $name:ident() -> $ty:ty $body:block ) ; )+
        }
    ) => {
        impl $owner {
            $( $macro_!(for $owner; $(#[$meta])* $vis fn $name() -> $ty $body); )+

            /// Registers the properties of the type in declaration order.
            /// Called by the static initialisation of the type.
            #[doc(hidden)]
            pub fn __register_properties() {
                $( let _ = <$owner>::$name(); )+
                $($( $more(); )*)?
            }
        }
    };

    // A part of the properties of a type, wrapping `ferro_property!(..);`.
    (
        impl $owner:ident, fn $part:ident {
            $( $macro_:ident ! ( $(#[$meta:meta])* $vis:vis fn $name:ident() -> $ty:ty $body:block ) ; )+
        }
    ) => {
        impl $owner {
            $( $macro_!(for $owner; $(#[$meta])* $vis fn $name() -> $ty $body); )+

            /// Registers a part of the properties of the type; named by its
            /// main `ferro_properties!` block.
            #[doc(hidden)]
            pub fn $part() {
                $( let _ = <$owner>::$name(); )+
            }
        }
    };

    // A part of the properties of a type.
    (
        impl $owner:ident, fn $part:ident {
            $( $(#[$meta:meta])* $vis:vis fn $name:ident() -> $ty:ty $body:block )*
        }
    ) => {
        impl $owner {
            $crate::ferro_properties!(@accessors $owner { $( $(#[$meta])* $vis fn $name() -> $ty $body )* });

            /// Registers a part of the properties of the type; named by its
            /// main `ferro_properties!` block.
            #[doc(hidden)]
            pub fn $part() {
                $( let _ = <$owner>::$name(); )*
            }
        }
    };

    // The main block.
    (
        impl $owner:ident $(, also [$($more:path),* $(,)?])? {
            $( $(#[$meta:meta])* $vis:vis fn $name:ident() -> $ty:ty $body:block )*
        }
    ) => {
        impl $owner {
            $crate::ferro_properties!(@accessors $owner { $( $(#[$meta])* $vis fn $name() -> $ty $body )* });

            /// Registers the properties of the type in declaration order.
            /// Called by the static initialisation of the type.
            #[doc(hidden)]
            pub fn __register_properties() {
                $( let _ = <$owner>::$name(); )*
                $($( $more(); )*)?
            }
        }
    };
}

use crate::data::BindingMode;
use crate::property_store::EffectiveValue;
use crate::{FerroObject, TypeInfo};
use std::cell::RefCell;
use std::rc::Rc;

/// Metadata common to all property kinds.
#[derive(Clone, Debug)]
pub struct FerroPropertyMetadata {
    default_binding_mode: BindingMode,
    enable_data_validation: Option<bool>,
    is_read_only: bool,
}

impl FerroPropertyMetadata {
    pub fn new(default_binding_mode: BindingMode, enable_data_validation: Option<bool>) -> Self {
        Self { default_binding_mode, enable_data_validation, is_read_only: false }
    }

    /// The default binding mode for the property.
    pub fn default_binding_mode(&self) -> BindingMode {
        if self.default_binding_mode == BindingMode::Default {
            BindingMode::OneWay
        } else {
            self.default_binding_mode
        }
    }

    /// Whether the property is interested in data validation.
    ///
    /// Data validation is validation performed at the target of a binding, for
    /// example in a view model. To enable it on a binding, the property must
    /// also enable it here.
    pub fn enable_data_validation(&self) -> Option<bool> {
        self.enable_data_validation
    }

    /// Whether the metadata has been frozen.
    pub fn is_read_only(&self) -> bool {
        self.is_read_only
    }

    /// Merges unset members from the base metadata.
    pub fn merge(&mut self, base: &FerroPropertyMetadata) {
        assert!(!self.is_read_only, "The metadata is read-only.");
        if self.default_binding_mode == BindingMode::Default {
            self.default_binding_mode = base.default_binding_mode();
        }
        if self.enable_data_validation.is_none() {
            self.enable_data_validation = base.enable_data_validation;
        }
    }

    /// Makes the metadata read-only.
    pub fn freeze(&mut self) {
        self.is_read_only = true;
    }
}

/// The coercion callback of a styled property.
pub type CoerceValueCallback<T> = Rc<dyn Fn(&FerroObject, T) -> T>;

/// The small typed operations used by explicit recoercion. These functions
/// already serve ordinary typed writes; keeping them separate lets the cold
/// two-value algorithm require only the public metadata's `Clone` bound.
pub(crate) struct CoercionOperations<T> {
    pub(crate) equals: fn(&T, &T) -> bool,
    pub(crate) notify_value_changed: fn(&EffectiveValue<T>, &FerroObject, T),
    pub(crate) notify_base_value_changed: fn(&EffectiveValue<T>, &FerroObject),
}

pub(crate) struct DefaultCoercionOperations<T> {
    pub(crate) equals: fn(&T, &T) -> bool,
    pub(crate) set_default: fn(&EffectiveValue<T>, &FerroObject, T),
}

/// The factory borrows the store, owner and typed property. Keeping that
/// PropertyValue-specific construction outside the algorithm lets public
/// Clone-only metadata retain its existing bounds.
pub(crate) trait DefaultEffectiveValueFactory<T> {
    fn create_and_add(&self) -> Rc<EffectiveValue<T>>;
}

// Requests contain only borrows and function pointers: no owned T, Rc or
// observable destructor crosses this dispatch frame. One entry covers all
// coercion paths without enlarging metadata for additional algorithm slots.
enum CoercionRequest<'a, T> {
    Recoerce {
        target: &'a EffectiveValue<T>,
        owner: &'a FerroObject,
        operations: CoercionOperations<T>,
    },
    EndReevaluation {
        target: &'a EffectiveValue<T>,
        owner: &'a FerroObject,
        operations: DefaultCoercionOperations<T>,
    },
    Default {
        coercion: &'a Coercion<T>,
        metadata: &'a StyledPropertyMetadata<T>,
        owner: &'a FerroObject,
        factory: &'a dyn DefaultEffectiveValueFactory<T>,
        operations: DefaultCoercionOperations<T>,
    },
}

/// Constructed only when a caller supplies a coercer. A property without a
/// coercer must not take the address of its cold algorithms merely because
/// its untyped effective-value and property interfaces expose coercion.
pub(crate) struct Coercion<T> {
    callback: CoerceValueCallback<T>,
    apply: for<'a> fn(CoercionRequest<'a, T>),
}

impl<T> Clone for Coercion<T> {
    fn clone(&self) -> Self {
        // Copy the algorithm address without cloning T or wrapping the
        // callback: metadata continues to share the original Rc allocation.
        Self { callback: self.callback.clone(), apply: self.apply }
    }
}

impl<T> Coercion<T> {
    pub(crate) fn callback(&self) -> &CoerceValueCallback<T> {
        &self.callback
    }

    pub(crate) fn apply(&self, target: &EffectiveValue<T>, owner: &FerroObject, operations: CoercionOperations<T>) {
        (self.apply)(CoercionRequest::Recoerce { target, owner, operations });
    }

    pub(crate) fn end_reevaluation(
        &self,
        target: &EffectiveValue<T>,
        owner: &FerroObject,
        operations: DefaultCoercionOperations<T>,
    ) {
        (self.apply)(CoercionRequest::EndReevaluation { target, owner, operations });
    }

    pub(crate) fn coerce_default(
        &self,
        metadata: &StyledPropertyMetadata<T>,
        owner: &FerroObject,
        factory: &dyn DefaultEffectiveValueFactory<T>,
        operations: DefaultCoercionOperations<T>,
    ) {
        (self.apply)(CoercionRequest::Default { coercion: self, metadata, owner, factory, operations });
    }
}

impl<T: Clone + 'static> Coercion<T> {
    pub(crate) fn new(callback: CoerceValueCallback<T>) -> Self {
        Self { callback, apply: Self::dispatch }
    }

    fn dispatch(request: CoercionRequest<'_, T>) {
        match request {
            CoercionRequest::Recoerce { target, owner, operations } => target.apply_coercion(owner, operations),
            CoercionRequest::EndReevaluation { target, owner, operations } => {
                target.apply_coercion_at_end(owner, operations);
            }
            CoercionRequest::Default { coercion, metadata, owner, factory, operations } => {
                coercion.apply_default(metadata, owner, factory, operations);
            }
        }
    }

    fn apply_default(
        &self,
        metadata: &StyledPropertyMetadata<T>,
        owner: &FerroObject,
        factory: &dyn DefaultEffectiveValueFactory<T>,
        operations: DefaultCoercionOperations<T>,
    ) {
        let coerce = &self.callback;
        // The outer typed route retains the original metadata Rc. Keep all
        // owned values in this frame through application and cleanup; never
        // return an owned coerced T after releasing default or metadata.
        let default = metadata.default_value().clone();
        let coerced = coerce(owner, default.clone());
        if (operations.equals)(&default, &coerced) {
            return;
        }
        // Construction reloads current metadata, as it originally did after
        // a potentially reentrant coercer/equality implementation.
        let effective = factory.create_and_add();
        (operations.set_default)(&effective, owner, coerced);
    }
}

#[cfg(test)]
mod coercion_request_tests {
    use super::*;
    use std::mem::{align_of, needs_drop, size_of};

    #[test]
    fn borrowed_coercion_requests_keep_the_single_pointer_layout_and_unbounded_types() {
        struct DropOnly;
        impl Drop for DropOnly {
            fn drop(&mut self) { panic!("the request must not own this value"); }
        }
        type Original<T> = (
            CoerceValueCallback<T>,
            fn(&EffectiveValue<T>, &FerroObject, CoercionOperations<T>),
        );
        assert_eq!(size_of::<Coercion<DropOnly>>(), size_of::<Original<DropOnly>>());
        assert_eq!(align_of::<Coercion<DropOnly>>(), align_of::<Original<DropOnly>>());
        assert_eq!(size_of::<Option<Coercion<DropOnly>>>(), size_of::<Option<Original<DropOnly>>>());
        assert!(!needs_drop::<CoercionRequest<'_, DropOnly>>());
        assert!(!needs_drop::<CoercionOperations<DropOnly>>());
        assert!(!needs_drop::<DefaultCoercionOperations<DropOnly>>());
        assert_eq!(size_of::<CoercionRequest<'_, DropOnly>>(), size_of::<CoercionRequest<'_, String>>());

        // Naming public metadata must not acquire Clone, PartialEq or 'static
        // bounds just because its private dispatch field names a request.
        let _: Option<StyledPropertyMetadata<DropOnly>> = None;
        fn borrowed<'a>(_: &'a ()) -> Option<StyledPropertyMetadata<&'a ()>> { None }
        let local = ();
        assert!(borrowed(&local).is_none());
    }
}

/// Metadata for styled properties.
pub struct StyledPropertyMetadata<T> {
    base: FerroPropertyMetadata,
    default_value: Option<T>,
    coerce: Option<Coercion<T>>,
}

impl<T: Clone> Clone for StyledPropertyMetadata<T> {
    fn clone(&self) -> Self {
        Self { base: self.base.clone(), default_value: self.default_value.clone(), coerce: self.coerce.clone() }
    }
}

impl<T> std::ops::Deref for StyledPropertyMetadata<T> {
    type Target = FerroPropertyMetadata;
    fn deref(&self) -> &FerroPropertyMetadata {
        &self.base
    }
}

impl<T: Clone + 'static> StyledPropertyMetadata<T> {
    /// Creates metadata. A `default_value` of `None` inherits the default
    /// value of the base metadata when merged.
    pub fn new(default_value: Option<T>) -> Self {
        Self {
            base: FerroPropertyMetadata::new(BindingMode::Default, Some(false)),
            default_value,
            coerce: None,
        }
    }

    pub fn with_default_binding_mode(mut self, mode: BindingMode) -> Self {
        self.base.default_binding_mode = mode;
        self
    }

    pub fn with_coerce(self, coerce: impl Fn(&FerroObject, T) -> T + 'static) -> Self {
        self.with_registered_coercion(Coercion::new(Rc::new(coerce)))
    }

    pub(crate) fn with_registered_coercion(mut self, coerce: Coercion<T>) -> Self {
        self.coerce = Some(coerce);
        self
    }

    pub fn with_enable_data_validation(mut self, enable: bool) -> Self {
        self.base.enable_data_validation = Some(enable);
        self
    }

    /// The default value of the property. Panics if the metadata has not been
    /// merged with a base that provides one.
    #[inline]
    pub fn default_value(&self) -> &T {
        self.default_value.as_ref().expect("metadata has no default value")
    }

    pub(crate) fn has_default_value(&self) -> bool {
        self.default_value.is_some()
    }

    /// The value coercion callback, if any.
    #[inline]
    pub fn coerce_value(&self) -> Option<&CoerceValueCallback<T>> {
        self.coerce.as_ref().map(Coercion::callback)
    }

    pub(crate) fn coercion(&self) -> Option<&Coercion<T>> {
        self.coerce.as_ref()
    }
}

/// Metadata for direct properties.
#[derive(Clone)]
pub struct DirectPropertyMetadata<T> {
    base: FerroPropertyMetadata,
    unset_value: Option<T>,
}

impl<T> std::ops::Deref for DirectPropertyMetadata<T> {
    type Target = FerroPropertyMetadata;
    fn deref(&self) -> &FerroPropertyMetadata {
        &self.base
    }
}

impl<T: Clone + 'static> DirectPropertyMetadata<T> {
    pub fn new(unset_value: Option<T>) -> Self {
        Self { base: FerroPropertyMetadata::new(BindingMode::Default, None), unset_value }
    }

    pub fn with_default_binding_mode(mut self, mode: BindingMode) -> Self {
        self.base.default_binding_mode = mode;
        self
    }

    pub fn with_enable_data_validation(mut self, enable: bool) -> Self {
        self.base.enable_data_validation = Some(enable);
        self
    }

    /// The value to use when the property is set to the unset value.
    #[inline]
    pub fn unset_value(&self) -> &T {
        self.unset_value.as_ref().expect("metadata has no unset value")
    }
}

/// Behaviour shared by the typed metadata kinds so that [`MetadataTable`] can
/// manage them generically.
pub trait PropertyMetadata: Sized + 'static {
    fn base(&self) -> &FerroPropertyMetadata;
    fn merge(&mut self, base: &Self);
    fn freeze(&mut self);
    /// Returns metadata that is safe to use for any host type: a copy without
    /// host-specific callbacks.
    fn generate_type_safe_metadata(this: &Rc<Self>) -> Rc<Self>;
}

impl<T: Clone + 'static> PropertyMetadata for StyledPropertyMetadata<T> {
    fn base(&self) -> &FerroPropertyMetadata {
        &self.base
    }

    fn merge(&mut self, base: &Self) {
        self.base.merge(&base.base);
        if self.default_value.is_none() {
            self.default_value = base.default_value.clone();
        }
        if self.coerce.is_none() {
            self.coerce = base.coerce.clone();
        }
    }

    fn freeze(&mut self) {
        self.base.freeze();
    }

    fn generate_type_safe_metadata(this: &Rc<Self>) -> Rc<Self> {
        if this.is_read_only() && this.coerce.is_none() {
            return this.clone();
        }
        let mut copy = StyledPropertyMetadata::new(this.default_value.clone())
            .with_default_binding_mode(this.default_binding_mode())
            .with_enable_data_validation(this.enable_data_validation().unwrap_or(false));
        copy.freeze();
        Rc::new(copy)
    }
}

impl<T: Clone + 'static> PropertyMetadata for DirectPropertyMetadata<T> {
    fn base(&self) -> &FerroPropertyMetadata {
        &self.base
    }

    fn merge(&mut self, base: &Self) {
        self.base.merge(&base.base);
        if self.unset_value.is_none() {
            self.unset_value = base.unset_value.clone();
        }
    }

    fn freeze(&mut self) {
        self.base.freeze();
    }

    fn generate_type_safe_metadata(this: &Rc<Self>) -> Rc<Self> {
        this.clone()
    }
}

/// Per-host-type metadata storage of a property, with the lookup rules of the
/// property system: the metadata registered for the nearest base class of the
/// queried type wins, falling back to the type-safe default metadata.
pub(crate) struct MetadataTable<M> {
    default_metadata: Rc<M>,
    inner: RefCell<MetadataEntries<M>>,
}

// The normal property has only its registration. Do not allocate the host
// index or cache until a second host actually provides different metadata.
enum MetadataEntries<M> {
    Single(Option<(&'static TypeInfo, Rc<M>)>),
    Multiple(Box<MetadataOverrides<M>>),
}

struct MetadataOverrides<M> {
    hosts: MetadataHosts,
    values: Vec<Rc<M>>,
}

// Slots are stable until a registration changes. All metadata types share the
// hierarchy lookup and its cache, while the values stay strongly typed.
struct MetadataHosts {
    owners: Vec<&'static TypeInfo>,
    // Each key is a non-null, process-lifetime TypeInfo address. The cache grows
    // by powers of two and stays at most half full so every probe terminates.
    // Removing or adding an owner invalidates every inherited slot at once.
    slots: Vec<(usize, usize)>,
    occupied: usize,
}

impl MetadataHosts {
    fn new(first: &'static TypeInfo, second: &'static TypeInfo) -> Self {
        Self { owners: vec![first, second], slots: Vec::new(), occupied: 0 }
    }

    #[inline]
    fn bucket(key: usize, capacity: usize) -> usize {
        // Adjacent records have an odd stride after the shift. Fold higher
        // address bits into the index for independently aligned type descriptors.
        let hash = key >> std::mem::size_of::<TypeInfo>().trailing_zeros();
        (hash ^ (hash >> 7)) & (capacity - 1)
    }

    #[inline]
    fn resolve(&mut self, host: &'static TypeInfo) -> usize {
        let key = host as *const TypeInfo as usize;
        if !self.slots.is_empty() {
            let bucket = Self::bucket(key, self.slots.len());
            let (cached, slot) = self.slots[bucket];
            if cached == key {
                return slot;
            }
        }
        self.resolve_other(host, key)
    }

    #[inline(never)]
    fn resolve_other(&mut self, host: &'static TypeInfo, key: usize) -> usize {
        if !self.slots.is_empty() {
            let bucket = Self::find(&self.slots, key);
            if self.slots[bucket].0 != 0 {
                return self.slots[bucket].1;
            }
        }
        if self.occupied == self.slots.len() / 2 {
            let mut slots = vec![(0, 0); (self.slots.len() * 2).max(4)];
            for &(cached, slot) in &self.slots {
                if cached != 0 {
                    let bucket = Self::find(&slots, cached);
                    slots[bucket] = (cached, slot);
                }
            }
            self.slots = slots;
        }
        let bucket = Self::find(&self.slots, key);
        let slot = inherited_metadata_index(&self.owners, host).unwrap_or(usize::MAX);
        self.slots[bucket] = (key, slot);
        self.occupied += 1;
        slot
    }

    #[inline]
    fn find(slots: &[(usize, usize)], key: usize) -> usize {
        let mut bucket = Self::bucket(key, slots.len());
        while slots[bucket].0 != 0 && slots[bucket].0 != key {
            bucket = (bucket + 1) & (slots.len() - 1);
        }
        bucket
    }

    fn invalidate(&mut self) {
        self.slots.fill((0, 0));
        self.occupied = 0;
    }
}

fn host_index(hosts: &[&'static TypeInfo], host: &'static TypeInfo) -> Option<usize> {
    hosts.iter().position(|owner| std::ptr::eq(*owner, host))
}

fn inherited_metadata_index(hosts: &[&'static TypeInfo], host: &'static TypeInfo) -> Option<usize> {
    let mut current = Some(host);
    while let Some(t) = current {
        if let Some(index) = host_index(hosts, t) { return Some(index); }
        current = t.base_type();
    }
    None
}

impl<M: PropertyMetadata> MetadataTable<M> {
    pub fn new(host_type: &'static TypeInfo, mut metadata: M) -> Self {
        metadata.freeze();
        let metadata = Rc::new(metadata);
        let default_metadata = M::generate_type_safe_metadata(&metadata);
        Self {
            default_metadata,
            inner: RefCell::new(MetadataEntries::Single(Some((host_type, metadata)))),
        }
    }

    /// A table for a property that shares its identity with `source` (added
    /// owner) and optionally carries metadata for the new owner.
    pub fn for_added_owner(source: &Self, owner_type: &'static TypeInfo, metadata: Option<M>) -> Self {
        Self {
            default_metadata: source.default_metadata.clone(),
            inner: RefCell::new(MetadataEntries::Single(metadata.map(|m| (owner_type, Rc::new(m))))),
        }
    }

    #[inline]
    pub fn default_metadata(&self) -> &Rc<M> {
        &self.default_metadata
    }

    pub fn get(&self, type_: &'static TypeInfo) -> Rc<M> {
        let mut inner = self.inner.borrow_mut();
        let table = match &mut *inner {
            MetadataEntries::Single(Some((host, value))) => {
                return if Rc::ptr_eq(value, &self.default_metadata) || host.is_assignable_from(type_) {
                    value.clone()
                } else {
                    self.default_metadata.clone()
                };
            }
            MetadataEntries::Single(None) => return self.default_metadata.clone(),
            MetadataEntries::Multiple(table) => table,
        };
        let slot = table.hosts.resolve(type_);
        table.values.get(slot).unwrap_or(&self.default_metadata).clone()
    }

    pub fn override_metadata(&self, property_name: &str, type_: &'static TypeInfo, mut metadata: M) {
        let exists = match &*self.inner.borrow() {
            MetadataEntries::Single(existing) => existing.as_ref().is_some_and(|(t, _)| std::ptr::eq(*t, type_)),
            MetadataEntries::Multiple(table) => host_index(&table.hosts.owners, type_).is_some(),
        };
        if exists {
            panic!("Metadata is already set for {property_name} on {type_}.");
        }
        let base = self.get(type_);
        metadata.merge(&base);
        metadata.freeze();
        let value = Rc::new(metadata);
        let mut inner = self.inner.borrow_mut();
        match &mut *inner {
            MetadataEntries::Single(existing) => {
                if let Some((host, original)) = existing.take() {
                    *inner = MetadataEntries::Multiple(Box::new(MetadataOverrides {
                        hosts: MetadataHosts::new(host, type_),
                        values: vec![original, value],
                    }));
                } else {
                    *existing = Some((type_, value));
                }
            }
            MetadataEntries::Multiple(table) => {
                table.hosts.owners.push(type_);
                table.values.push(value);
                table.hosts.invalidate();
            }
        }
    }

    pub fn unregister(&self, type_: &'static TypeInfo) {
        let mut inner = self.inner.borrow_mut();
        match &mut *inner {
            MetadataEntries::Single(existing) => {
                if existing.as_ref().is_some_and(|(t, _)| std::ptr::eq(*t, type_)) {
                    *existing = None;
                }
            }
            MetadataEntries::Multiple(table) => {
                if let Some(i) = host_index(&table.hosts.owners, type_) {
                    table.hosts.owners.swap_remove(i);
                    table.values.swap_remove(i);
                    // Descendants may have cached the removed override.
                    table.hosts.invalidate();
                    if table.hosts.owners.len() == 1 {
                        let metadata = table.values.pop().expect("one registration remains");
                        *inner = MetadataEntries::Single(Some((table.hosts.owners[0], metadata)));
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod metadata_table_tests {
    use super::*;

    static ROOT: TypeInfo = TypeInfo::new("Root", None);
    static CHILD: TypeInfo = TypeInfo::new("Child", Some(&ROOT));
    static LEAF: TypeInfo = TypeInfo::new("Leaf", Some(&CHILD));
    static SIBLING: TypeInfo = TypeInfo::new("Sibling", Some(&ROOT));

    #[test]
    fn colliding_cache_entries_follow_replaced_and_removed_registrations() {
        static TYPES: [TypeInfo; 16] = [const { TypeInfo::new("Derived", Some(&CHILD)) }; 16];
        let table = MetadataTable::new(&ROOT, StyledPropertyMetadata::new(Some(1)));
        table.override_metadata("Number", &CHILD, StyledPropertyMetadata::new(Some(2)));
        table.override_metadata("Number", &TYPES[0], StyledPropertyMetadata::new(Some(3)));
        for _ in 0..2 {
            for (i, host) in TYPES.iter().enumerate() {
                assert_eq!(*table.get(host).default_value(), if i == 0 { 3 } else { 2 });
            }
        }
        table.unregister(&CHILD);
        for (i, host) in TYPES.iter().enumerate() {
            assert_eq!(*table.get(host).default_value(), if i == 0 { 3 } else { 1 });
        }
        table.override_metadata("Number", &CHILD, StyledPropertyMetadata::new(Some(4)));
        for (i, host) in TYPES.iter().enumerate().rev() {
            assert_eq!(*table.get(host).default_value(), if i == 0 { 3 } else { 4 });
        }
    }

    #[test]
    fn unregister_invalidates_inherited_and_relocated_overrides() {
        let table = MetadataTable::new(&ROOT, StyledPropertyMetadata::new(Some(1)));
        table.override_metadata("Number", &CHILD, StyledPropertyMetadata::new(Some(2)));
        table.override_metadata("Number", &SIBLING, StyledPropertyMetadata::new(Some(3)));
        assert_eq!(*table.get(&LEAF).default_value(), 2);
        assert_eq!(*table.get(&SIBLING).default_value(), 3);

        table.unregister(&CHILD);
        assert_eq!(*table.get(&LEAF).default_value(), 1);
        assert_eq!(*table.get(&SIBLING).default_value(), 3);
        table.override_metadata("Number", &CHILD, StyledPropertyMetadata::new(Some(4)));
        assert_eq!(*table.get(&LEAF).default_value(), 4);
    }
}

use super::{IValueEntry, ValueFrame};
use crate::data::{BindingError, BindingValue, BindingValueType};
use crate::reactive::{IDisposable, IObservable, IObserver, ObservableError};
use crate::{BoxedValue, FerroObject, FerroProperty, PropertyValue, Ref, StyledProperty};
use std::any::Any;
use std::cell::{Cell, RefCell};
use std::rc::{Rc, Weak};

// Source installation is shared for boxed bindings, while every delivery uses
// this typed cache. The adapter is installed by the selected overload, so a
// boxed source does not retain the typed-source observer implementations.
type EntryObserver<T, U> = fn(Weak<BindingEntry<T>>) -> Rc<dyn IObserver<U>>;

pub(crate) enum BindingSource<T: PropertyValue> {
    Typed(Rc<dyn IObservable<T>>, EntryObserver<T, T>),
    Value(Rc<dyn IObservable<BindingValue<T>>>, EntryObserver<T, BindingValue<T>>),
    Untyped(Rc<dyn IObservable<BoxedValue>>, EntryObserver<T, BoxedValue>),
}

impl<T: PropertyValue> BindingSource<T> {
    pub(crate) fn typed(source: Rc<dyn IObservable<T>>) -> Self {
        Self::Typed(source, |entry| Rc::new(TypedObserver(entry)))
    }

    pub(crate) fn value(source: Rc<dyn IObservable<BindingValue<T>>>) -> Self {
        Self::Value(source, |entry| Rc::new(ValueObserver(entry)))
    }

    pub(crate) fn untyped(source: Rc<dyn IObservable<BoxedValue>>) -> Self {
        Self::Untyped(source, |entry| Rc::new(UntypedObserver(entry)))
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum SubscriptionPhase {
    Idle,
    /// Subscribing; values produced during subscription are published.
    Creating,
    /// Subscribing; values produced during subscription are only stored.
    CreatingQuiet,
    Active,
}

/// Subscription and validation belong to the binding, regardless of its
/// property's Rust value type. Keep their reentrant transitions in one place.
pub(super) struct BindingEntryState {
    // The phase is readable while subscribing or disposing synchronously.
    phase: Cell<SubscriptionPhase>,
    subscription: Cell<Option<Rc<dyn IDisposable>>>,
    frame: Weak<dyn ValueFrame>,
    has_data_validation: bool,
    data_validation_state: Cell<BindingValueType>,
    data_validation_error: RefCell<Option<BindingError>>,
}

pub(super) struct BoundFrame {
    pub(super) owner: Ref<FerroObject>,
    frame: Rc<dyn ValueFrame>,
}

impl BoundFrame {
    #[inline]
    pub(super) fn publish(&self, entry: Rc<dyn IValueEntry>) {
        self.owner.values().on_binding_value_changed(&self.owner, &entry, self.frame.base().priority());
    }
}

impl BindingEntryState {
    pub(super) fn new(frame: Weak<dyn ValueFrame>, has_data_validation: bool) -> Self {
        Self {
            phase: Cell::new(SubscriptionPhase::Idle),
            subscription: Cell::new(None),
            frame,
            has_data_validation,
            data_validation_state: Cell::new(BindingValueType::VALUE),
            data_validation_error: RefCell::new(None),
        }
    }

    #[inline]
    pub(super) fn bound_frame(&self) -> Option<BoundFrame> {
        let frame = self.frame.upgrade()?;
        Some(BoundFrame { owner: frame.base().owner()?, frame })
    }

    pub(super) fn begin(&self, publish: bool) -> bool {
        if self.phase.get() != SubscriptionPhase::Idle {
            return false;
        }
        self.phase.set(if publish { SubscriptionPhase::Creating } else { SubscriptionPhase::CreatingQuiet });
        true
    }

    pub(super) fn finish(&self, subscription: Rc<dyn IDisposable>) {
        // A synchronous source may have completed during subscribe.
        if self.phase.get() == SubscriptionPhase::Idle {
            subscription.dispose();
        } else {
            self.phase.set(SubscriptionPhase::Active);
            self.subscription.set(Some(subscription));
        }
    }

    pub(super) fn publishes(&self) -> bool {
        matches!(self.phase.get(), SubscriptionPhase::Creating | SubscriptionPhase::Active)
    }

    #[inline]
    pub(super) fn set_validation(&self, state: BindingValueType, error: Option<&BindingError>) {
        if self.has_data_validation {
            self.data_validation_state.set(state);
            *self.data_validation_error.borrow_mut() = error.cloned();
        }
    }

    pub(super) fn validation(&self) -> Option<(BindingValueType, Option<BindingError>)> {
        self.has_data_validation
            .then(|| (self.data_validation_state.get(), self.data_validation_error.borrow().clone()))
    }

    pub(super) fn unsubscribe(&self) {
        self.phase.set(SubscriptionPhase::Idle);
        if let Some(s) = self.subscription.take() {
            s.dispose();
        }
    }

    pub(super) fn completed(&self, property: &'static FerroProperty) {
        self.phase.set(SubscriptionPhase::Idle);
        drop(self.subscription.take());
        if let Some(frame) = self.frame.upgrade() {
            frame.on_binding_completed(property);
        }
    }
}

impl Drop for BindingEntryState {
    fn drop(&mut self) {
        if let Some(s) = self.subscription.get_mut().take() {
            s.dispose();
        }
    }
}

/// A value entry in a value frame whose value is produced by an observable.
pub(crate) struct BindingEntry<T: PropertyValue> {
    // Drop the subscription before any of the objects its callbacks can use.
    state: BindingEntryState,
    this: Weak<BindingEntry<T>>,
    property: &'static StyledProperty<T>,
    source: BindingSource<T>,
    value: RefCell<Option<T>>,
    default_value: RefCell<Option<T>>,
}

impl<T: PropertyValue> BindingEntry<T> {
    pub fn new(
        target: &FerroObject,
        frame: Weak<dyn ValueFrame>,
        property: &'static StyledProperty<T>,
        source: BindingSource<T>,
    ) -> Rc<Self> {
        let has_data_validation = property.get_metadata_for(target).enable_data_validation() == Some(true);
        Rc::new_cyclic(|this| Self {
            this: this.clone(),
            state: BindingEntryState::new(frame, has_data_validation),
            property,
            source,
            value: RefCell::new(None),
            default_value: RefCell::new(None),
        })
    }

    /// Subscribes to the source if not already subscribed, publishing the
    /// values it produces.
    pub fn start(&self) {
        self.start_core(true)
    }

    #[inline]
    fn start_core(&self, produce_value: bool) {
        if self.state.begin(produce_value) {
            self.subscribe();
        }
    }

    // Active entries only read the phase when the store asks for a value.
    #[inline(never)]
    fn subscribe(&self) {
        // The observers hold the entry weakly (DEVIATIONS.md, Property
        // system): the entry holds its source, and the source its observers.
        let this = self.this.clone();
        let subscription = match &self.source {
            BindingSource::Typed(source, observer) => source.subscribe(observer(this)),
            BindingSource::Value(source, observer) => source.subscribe(observer(this)),
            BindingSource::Untyped(source, observer) => source.subscribe(observer(this)),
        };
        self.state.finish(subscription);
    }

    /// A value that fails validation becomes a binding error; the entry then
    /// falls back to the default value and reports the error to data
    /// validation.
    fn validate(&self, value: T) -> BindingValue<T> {
        if self.property.is_valid(&value) {
            BindingValue::new(value)
        } else {
            self.invalid_value()
        }
    }

    fn convert_and_validate(&self, value: BindingValue<T>) -> BindingValue<T> {
        if value.has_value() && !self.property.is_valid(value.value()) {
            return self.invalid_value();
        }
        value
    }

    fn invalid_value(&self) -> BindingValue<T> {
        BindingValue::binding_error(invalid_value_error(self.property))
    }

    fn set_value(self: &Rc<Self>, mut value: BindingValue<T>) {
        if value.value_type() == BindingValueType::DO_NOTHING {
            return;
        }
        let Some(bound) = self.state.bound_frame() else { return };

        if !value.has_value() && value.value_type() != BindingValueType::DATA_VALIDATION_ERROR {
            value = value.with_value(self.property.binding_default(&bound.owner, &self.default_value));
        }

        self.state.set_validation(value.value_type(), value.error());

        if value.has_value() {
            let changed = self.value.borrow().as_ref() != Some(value.value());
            if changed {
                // `replace` releases the borrow before the previous value is
                // dropped: dropping a value may run code that reads the property.
                self.value.replace(value.into_option());
                if self.state.publishes() {
                    bound.publish(self.clone());
                }
            }
        }
    }

    fn binding_completed(&self) {
        self.state.completed(self.property);
    }
}

impl<T: PropertyValue> IValueEntry for BindingEntry<T> {
    fn property(&self) -> &'static FerroProperty {
        self.property
    }

    fn has_value(&self) -> bool {
        self.start_core(false);
        self.value.borrow().is_some()
    }

    fn try_get_value(&self, out: &mut dyn Any) -> bool {
        self.start_core(false);
        match (out.downcast_mut::<Option<T>>(), &*self.value.borrow()) {
            (Some(out), Some(value)) => {
                *out = Some(value.clone());
                true
            }
            _ => false,
        }
    }

    fn get_value_boxed(&self) -> Option<BoxedValue> {
        self.start_core(false);
        self.value.borrow().as_ref().map(|v| Rc::new(v.clone()) as BoxedValue)
    }

    fn get_data_validation_state(&self) -> Option<(BindingValueType, Option<BindingError>)> {
        self.state.validation()
    }

    fn unsubscribe(&self) {
        self.state.unsubscribe();
    }
}

impl<T: PropertyValue> IDisposable for BindingEntry<T> {
    fn dispose(&self) {
        self.unsubscribe();
        self.binding_completed();
    }
}

/// The error of a value that fails the validation of the property (compiled
/// once, not per value type).
#[cold]
pub(super) fn invalid_value_error(property: &FerroProperty) -> BindingError {
    BindingError::message(format!("The value is not valid for property '{}'.", property.name()))
}

struct TypedObserver<T: PropertyValue>(Weak<BindingEntry<T>>);

impl<T: PropertyValue> IObserver<T> for TypedObserver<T> {
    fn on_next(&self, value: T) {
        let Some(entry) = self.0.upgrade() else { return };
        let value = entry.validate(value);
        entry.set_value(value);
    }
    fn on_error(&self, _error: ObservableError) {
        if let Some(entry) = self.0.upgrade() {
            entry.binding_completed()
        }
    }
    fn on_completed(&self) {
        if let Some(entry) = self.0.upgrade() {
            entry.binding_completed()
        }
    }
}

struct ValueObserver<T: PropertyValue>(Weak<BindingEntry<T>>);

impl<T: PropertyValue> IObserver<BindingValue<T>> for ValueObserver<T> {
    fn on_next(&self, value: BindingValue<T>) {
        let Some(entry) = self.0.upgrade() else { return };
        let value = entry.convert_and_validate(value);
        entry.set_value(value);
    }
    fn on_error(&self, _error: ObservableError) {
        if let Some(entry) = self.0.upgrade() {
            entry.binding_completed()
        }
    }
    fn on_completed(&self) {
        if let Some(entry) = self.0.upgrade() {
            entry.binding_completed()
        }
    }
}

struct UntypedObserver<T: PropertyValue>(Weak<BindingEntry<T>>);

impl<T: PropertyValue> IObserver<BoxedValue> for UntypedObserver<T> {
    fn on_next(&self, value: BoxedValue) {
        let Some(entry) = self.0.upgrade() else { return };
        let value = entry.property.from_untyped(value.as_any());
        let value = entry.convert_and_validate(value);
        entry.set_value(value);
    }
    fn on_error(&self, _error: ObservableError) {
        if let Some(entry) = self.0.upgrade() {
            entry.binding_completed()
        }
    }
    fn on_completed(&self) {
        if let Some(entry) = self.0.upgrade() {
            entry.binding_completed()
        }
    }
}

