type EffectiveValueRef = Rc<dyn EffectiveValueDyn>;

// Borrowing only references keeps the factory vtable free of owning drop
// glue. The returned Rc is the original local, with no extra clone.
struct CoercedDefaultFactory<'a, T: PropertyValue> {
    store: &'a ValueStore,
    owner: &'a FerroObject,
    property: &'static StyledProperty<T>,
}

impl<T: PropertyValue> DefaultEffectiveValueFactory<T> for CoercedDefaultFactory<'_, T> {
    fn create_and_add(&self) -> Rc<EffectiveValue<T>> {
        let effective = self.store.create_effective_value(self.owner, self.property);
        self.store.add_effective_value(self.owner, self.property, effective.clone());
        // No other owning locals or callable temporaries remain after this
        // result is formed. On insertion unwind, effective still drops before
        // the caller's coerced/default values and retained metadata.
        effective
    }
}

/// The value of an inherited property before and after a change of the
/// inheritance ancestor: the effective value the old ancestors hold for it
/// and the one the new ancestors hold, either of which may be absent.
struct OldNewValue {
    property: &'static FerroProperty,
    old: Option<EffectiveValueRef>,
    new: Option<EffectiveValueRef>,
}

/// The most lists the pool below keeps (the size of the pool of the
/// original).
const MAX_OLD_NEW_VALUES_POOL_SIZE: usize = 4;

crate::ferro_thread_local! {
    /// The lists in which [`ValueStore::set_inheritance_parent`] pairs the
    /// old and the new inherited values, kept for the next change (the pool
    /// of property dictionaries of the original): a change takes a list
    /// from the pool, or makes one when the pool is empty (a change that
    /// happens inside the notifications of another has its own list), and
    /// gives it back empty.
    static OLD_NEW_VALUES_POOL: RefCell<Vec<Vec<OldNewValue>>> = const { RefCell::new(Vec::new()) };
}

crate::ferro_thread_local! {
    /// Not upstream: the lists in which a reevaluation copies the effective
    /// values it visits at its end, kept for the next reevaluation (a
    /// reevaluation inside the notifications of another takes a list of its
    /// own), so that a reevaluation does not allocate one.
    static REEVALUATION_LISTS: RefCell<Vec<Vec<EffectiveValueRef>>> = const { RefCell::new(Vec::new()) };
}

/// Stores the styled property values of a [`FerroObject`] and resolves the
/// effective value of each property from the values supplied at different
/// priorities.
///
/// The store lives inside its owner; every operation takes the owner so that
/// change notifications can be raised on it.
pub(crate) struct ValueStore {
    /// Value frames ordered from lowest to highest precedence.
    frames: RefCell<Vec<Rc<dyn ValueFrame>>>,
    #[cfg(all(debug_assertions, feature = "hot-reload"))]
    local_write_versions: RefCell<Vec<(u32, u64, u64)>>,
    local_value_bindings: RefCell<Vec<(u32, Rc<dyn IDisposable>)>>,
    /// The local value bindings that are binding expressions.
    local_value_expressions: RefCell<Vec<(u32, Rc<dyn BindingExpressionBase>)>>,
    /// Effective values sorted by property ID.
    effective_values: RefCell<Vec<(u32, EffectiveValueRef)>>,
    inherited_value_count: Cell<u32>,
    is_evaluating: Cell<u32>,
    frame_generation: Cell<u32>,
    styling: Cell<u32>,
    /// The nearest ancestor that holds inherited values. `Some(Weak)` pointing
    /// at the owner itself when the owner holds inherited values.
    inheritance_ancestor: RefCell<Option<WeakRef<FerroObject>>>,
}

impl ValueStore {
    pub fn new() -> Self {
        Self {
            frames: RefCell::new(Vec::new()),
            #[cfg(all(debug_assertions, feature = "hot-reload"))]
            local_write_versions: RefCell::new(Vec::new()),
            local_value_bindings: RefCell::new(Vec::new()),
            local_value_expressions: RefCell::new(Vec::new()),
            effective_values: RefCell::new(Vec::new()),
            inherited_value_count: Cell::new(0),
            is_evaluating: Cell::new(0),
            frame_generation: Cell::new(0),
            styling: Cell::new(0),
            inheritance_ancestor: RefCell::new(None),
        }
    }

    #[cfg(all(debug_assertions, feature = "hot-reload"))]
    pub fn local_write_version(&self, property: &FerroProperty) -> u64 {
        let mut versions = self.local_write_versions.borrow_mut();
        if let Some((_, version, _)) = versions.iter().find(|(id, _, _)| *id == property.id()) {
            return *version;
        }
        versions.push((property.id(), 0, 0));
        0
    }

    #[cfg(all(debug_assertions, feature = "hot-reload"))]
    pub fn local_assignment_version(&self, property: &FerroProperty) -> u64 {
        self.local_write_version(property);
        self.local_write_versions.borrow().iter()
            .find(|(id, _, _)| *id == property.id()).unwrap().2
    }

    #[cfg(all(debug_assertions, feature = "hot-reload"))]
    fn record_local_write(&self, property: &FerroProperty) {
        if let Some((_, version, assignment)) = self.local_write_versions.borrow_mut().iter_mut().find(|(id, _, _)| *id == property.id()) {
            *version = version.checked_add(1).expect("local write version overflow");
            *assignment = assignment.checked_add(1).expect("local assignment version overflow");
        }
    }

    #[cfg(all(debug_assertions, feature = "hot-reload"))]
    fn record_current_write(&self, property: &FerroProperty) {
        if let Some((_, version, _)) = self.local_write_versions.borrow_mut().iter_mut().find(|(id, _, _)| *id == property.id()) {
            *version = version.checked_add(1).expect("local write version overflow");
        }
    }

    pub fn is_evaluating(&self) -> bool {
        self.is_evaluating.get() > 0
    }

    pub fn frames(&self) -> Vec<Rc<dyn ValueFrame>> {
        self.frames.borrow().clone()
    }

    /// The frame at `index` (`_frames[i]`): the reevaluations read the frames
    /// by index from the last, as the original, instead of copying the list
    /// for every property they reevaluate. An index past the end panics, as
    /// the original throws.
    fn frame_at(&self, index: usize) -> Rc<dyn ValueFrame> {
        self.frames.borrow()[index].clone()
    }

    pub fn inheritance_ancestor(&self) -> Option<Ref<FerroObject>> {
        self.inheritance_ancestor.borrow().as_ref().and_then(WeakRef::upgrade)
    }

    pub fn begin_styling(&self) {
        self.styling.set(self.styling.get() + 1);
    }

    pub fn end_styling(&self, owner: &FerroObject) {
        let styling = self.styling.get() - 1;
        self.styling.set(styling);
        if styling == 0 {
            self.reevaluate_effective_values(owner, None);
        }
    }

    pub fn add_frame(&self, owner: &FerroObject, frame: Rc<dyn ValueFrame>) {
        self.insert_frame(owner, frame);
        self.reevaluate_effective_values(owner, None);
    }

    /// Adds a binding to a styled property.
    pub fn add_binding<T: PropertyValue, U: 'static>(
        &self,
        owner: &FerroObject,
        property: &'static StyledProperty<T>,
        source: Rc<dyn IObservable<U>>,
        priority: BindingPriority,
        start_local: fn(&Rc<LocalValueBindingObserver<T>>, Rc<dyn IObservable<U>>),
        frame_source: fn(Rc<dyn IObservable<U>>) -> BindingSource<T>,
    ) -> Rc<dyn IDisposable> {
        if priority == BindingPriority::LocalValue {
            let observer = LocalValueBindingObserver::new(owner, property);
            self.dispose_existing_local_value_binding(property);
            self.set_local_value_binding(property, observer.clone());
            start_local(&observer, source);
            observer
        } else {
            let effective = self.get_effective_value(property);
            let frame = self.get_or_create_immediate_value_frame(owner, property, priority);
            let result = frame.add_binding(property, frame_source(source));
            if effective.is_none_or(|e| priority <= e.priority()) {
                result.start();
            }
            result
        }
    }

    /// Installs a boxed source without specializing subscription ownership and
    /// priority selection for every property value type. The typed routes only
    /// construct the inline cache and its weak observer.
    pub fn add_boxed_binding(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        source: Rc<dyn IObservable<BoxedValue>>,
        priority: BindingPriority,
    ) -> Rc<dyn IDisposable> {
        if priority == BindingPriority::LocalValue {
            let observer = property.routes().route_create_boxed_local_binding(owner);
            self.dispose_existing_local_value_binding(property);
            self.set_local_value_binding(property, observer.clone());
            observer.start(source);
            observer
        } else {
            let effective = self.get_effective_value(property);
            let frame = self.get_or_create_immediate_value_frame(owner, property, priority);
            let result = frame.add_boxed_binding(property, source);
            if effective.is_none_or(|e| priority <= e.priority()) {
                result.start();
            }
            result
        }
    }

    /// Adds a binding to a direct property.
    pub fn add_direct_binding<T: PropertyValue, U: 'static>(
        &self,
        owner: &FerroObject,
        property: &'static DirectPropertyBase<T>,
        source: Rc<dyn IObservable<U>>,
        start: fn(&Rc<DirectBindingObserver<T>>, Rc<dyn IObservable<U>>),
    ) -> Rc<dyn IDisposable> {
        let observer = DirectBindingObserver::new(owner, property);
        self.dispose_existing_local_value_binding(property);
        self.set_local_value_binding(property, observer.clone());
        start(&observer, source);
        observer
    }

    /// Adds a binding expression to a property. The expression's default
    /// priority decides where it is stored; bindings to direct properties
    /// always have local value priority.
    pub fn add_binding_expression(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        source: Rc<dyn BindingExpressionBase>,
    ) -> Rc<dyn BindingExpressionBase> {
        let priority = source.default_priority();
        self.add_binding_expression_with_priority(owner, property, source, priority)
    }

    /// [`add_binding_expression`](Self::add_binding_expression) at the given priority instead of
    /// the expression's default priority (an addition: the values of WinUI's visual states are
    /// bound at animation priority).
    pub fn add_binding_expression_with_priority(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        source: Rc<dyn BindingExpressionBase>,
        priority: BindingPriority,
    ) -> Rc<dyn BindingExpressionBase> {
        if priority == BindingPriority::LocalValue || property.is_direct() {
            self.dispose_existing_local_value_binding(property);
            let disposable: Rc<dyn IDisposable> = source.clone();
            self.set_local_value_binding(property, disposable);
            self.local_value_expressions.borrow_mut().push((property.id(), source.clone()));
            source.attach(SinkRef::Store(owner.to_weak()), None, owner, property, BindingPriority::LocalValue);
            source.start(true);
        } else {
            let effective = self.get_effective_value(property);
            let frame = self.get_or_create_immediate_value_frame(owner, property, priority);
            source.attach(SinkRef::Store(owner.to_weak()), Some(Rc::downgrade(&frame)), owner, property, priority);
            frame.add_binding_expression(source.clone());
            if effective.is_none_or(|e| priority <= e.priority()) {
                source.start(true);
            }
        }
        source
    }

    /// The binding expression that is currently active on the property, if
    /// any.
    pub fn get_expression(&self, property: &'static FerroProperty) -> Option<Rc<dyn BindingExpressionBase>> {
        let local = || {
            self.local_value_expressions
                .borrow()
                .iter()
                .find(|(id, _)| *id == property.id())
                .map(|(_, e)| e.clone())
        };
        let has_local = self.local_value_bindings.borrow().iter().any(|(id, _)| *id == property.id());

        for frame in self.frames().iter().rev() {
            if frame.base().priority() > BindingPriority::LocalValue && has_local {
                return local();
            }
            if let (Some(entry), _) = frame.try_get_entry_if_active(property) {
                return entry.as_binding_expression();
            }
        }
        local()
    }

    #[cfg(all(debug_assertions, feature = "hot-reload"))]
    pub(crate) fn detach_expression_for_reload(
        &self,
        property: &'static FerroProperty,
        expression: &Rc<dyn BindingExpressionBase>,
    ) -> bool {
        let mut expressions = self.local_value_expressions.borrow_mut();
        let Some(index) = expressions.iter().position(|(id, value)| {
            *id == property.id() && Rc::ptr_eq(value, expression)
        }) else {
            return false;
        };
        expressions.remove(index);
        self.local_value_bindings.borrow_mut().retain(|(id, _)| *id != property.id());
        self.record_local_write(property);
        true
    }

    /// Reinstalls a paused expression whose sink still points at this store.
    /// It must not be attached or started again: that would recreate subscriptions
    /// and discard pending user input and validation.
    #[cfg(all(debug_assertions, feature = "hot-reload"))]
    pub(crate) fn restore_expression_after_reload(
        &self,
        property: &'static FerroProperty,
        expression: Rc<dyn BindingExpressionBase>,
    ) {
        assert!(!self.has_local_value_binding(property));
        self.set_local_value_binding(property, expression.clone());
        self.local_value_expressions.borrow_mut().push((property.id(), expression));
    }

    fn is_current_local_expression(
        &self,
        property: &'static FerroProperty,
        expression: &Rc<dyn BindingExpressionBase>,
    ) -> bool {
        self.local_value_expressions.borrow().iter().any(|(id, value)| {
            *id == property.id() && Rc::ptr_eq(value, expression)
        })
    }

    /// Called by a binding expression attached to this store when its value
    /// or error state changes.
    pub fn on_expression_changed(
        &self,
        owner: &FerroObject,
        instance: &Rc<dyn BindingExpressionBase>,
        has_value_changed: bool,
        has_error_changed: bool,
    ) {
        let property = instance.target_property().expect("the binding expression is attached");
        // A reload transaction can keep a detached expression subscribed while
        // another expression owns the slot. Only the current owner may publish.
        if instance.priority() == BindingPriority::LocalValue
            && !self.is_current_local_expression(property, instance)
        {
            return;
        }
        let entry: Rc<dyn IValueEntry> = instance.clone();

        if property.is_direct() {
            if has_value_changed {
                property.routes().route_set_direct_value_unchecked(owner, &*entry);
            }
        } else if has_value_changed {
            let priority = instance.priority();
            if priority == BindingPriority::LocalValue {
                let effective = self.get_or_add_effective_value(owner, property);
                effective.set_local_value_and_raise_entry(owner, &*entry);
            } else {
                match self.get_effective_value(property) {
                    Some(existing) => {
                        if priority <= existing.base_priority() {
                            self.reevaluate_effective_value(owner, property, Some(existing), Some(&entry), false);
                        }
                    }
                    None => self.add_effective_value_and_raise(owner, property, &entry, priority),
                }
            }
        }

        if has_error_changed {
            if let Some((state, error)) = entry.get_data_validation_state() {
                owner.on_update_data_validation(property, state, error);
            }
        }
    }

    /// Called by a binding expression attached to this store when it
    /// completes.
    pub fn on_expression_completed(&self, owner: &FerroObject, instance: &Rc<dyn BindingExpressionBase>) {
        let property = instance.target_property().expect("the binding expression is attached");
        // Disposing a retired expression must not clear its replacement's
        // validation state (nor its value).
        if instance.priority() == BindingPriority::LocalValue
            && !self.is_current_local_expression(property, instance)
        {
            return;
        }

        if instance.is_data_validation_enabled() {
            owner.on_update_data_validation(property, BindingValueType::UNSET_VALUE, None);
        }

        if instance.priority() == BindingPriority::LocalValue {
            self.on_local_value_binding_completed(owner, property, instance.as_ref());
        }
    }

    pub fn clear_value(&self, owner: &FerroObject, property: &'static FerroProperty) {
        #[cfg(all(debug_assertions, feature = "hot-reload"))]
        self.record_local_write(property);
        if let Some(effective) = self.get_effective_value(property) {
            if effective.priority() == BindingPriority::LocalValue || effective.is_overriden_current_value() {
                effective.set_is_overriden_current_value(false);
                self.reevaluate_effective_value(owner, property, Some(effective), None, true);
            }
        }
    }

    pub fn set_value<T: PropertyValue>(
        &self,
        owner: &FerroObject,
        property: &'static StyledProperty<T>,
        value: T,
        priority: BindingPriority,
    ) -> Option<Rc<dyn IDisposable>> {
        if !property.is_valid(&value) {
            property.value_not_valid();
        }

        if priority != BindingPriority::LocalValue {
            let frame = self.get_or_create_immediate_value_frame(owner, property, priority);
            let result = frame.add_value(property, value);
            let entry: Rc<dyn IValueEntry> = result.clone();
            let effective = self.get_or_add_effective_value(owner, property);
            effective.set_and_raise(owner, &entry, priority);
            Some(result)
        } else {
            self.set_local_value(owner, property, value);
            None
        }
    }

    pub fn set_current_value<T: PropertyValue>(&self, owner: &FerroObject, property: &'static StyledProperty<T>, value: T) {
        #[cfg(all(debug_assertions, feature = "hot-reload"))]
        self.record_current_write(property);
        let effective = self.get_or_add_effective_value(owner, property);
        cast_effective_value::<T>(&*effective).set_current_value_and_raise(owner, value);
    }

    pub fn set_local_value<T: PropertyValue>(&self, owner: &FerroObject, property: &'static StyledProperty<T>, value: T) {
        #[cfg(all(debug_assertions, feature = "hot-reload"))]
        self.record_local_write(property);
        let effective = self.get_or_add_effective_value(owner, property);
        cast_effective_value::<T>(&*effective).set_local_value_and_raise(owner, value);
    }

    /// The value of a styled property: the effective value, else the inherited
    /// value, else the default value.
    #[inline]
    pub fn get_value<T: PropertyValue>(&self, owner: &FerroObject, property: &'static StyledProperty<T>) -> T {
        // <!> Performance critical method.
        {
            let values = self.effective_values.borrow();
            if let Some(index) = Self::find(&values, property.id()) {
                return cast_effective_value::<T>(&*values[index].1).value();
            }
        }
        if property.inherits() {
            self.inherited_or_default(owner, property)
        } else {
            property.get_default_value_for(owner)
        }
    }

    // Keep the inherited value's temporary Rc and its unwind cleanup off the
    // hot paths for a local value or the default of a non-inheriting property.
    #[inline(never)]
    fn inherited_or_default<T: PropertyValue>(&self, owner: &FerroObject, property: &'static StyledProperty<T>) -> T {
        match self.try_get_inherited_value(property) {
            Some(value) => cast_effective_value::<T>(&*value).value(),
            None => property.get_default_value_for(owner),
        }
    }

    pub fn is_animating(&self, property: &FerroProperty) -> bool {
        self.get_effective_value(property).is_some_and(|v| v.priority() <= BindingPriority::Animation)
    }

    pub fn is_set(&self, property: &FerroProperty) -> bool {
        Self::find(&self.effective_values.borrow(), property.id()).is_some()
    }

    pub fn has_local_value_binding(&self, property: &FerroProperty) -> bool {
        self.local_value_bindings.borrow().iter().any(|(id, _)| *id == property.id())
    }

    pub fn coerce_value(&self, owner: &FerroObject, property: &'static FerroProperty) {
        match self.get_effective_value(property) {
            Some(v) => v.coerce_value(owner),
            None => property.routes().route_coerce_default_value(owner),
        }
    }

    pub fn coerce_default_value<T: PropertyValue>(&self, owner: &FerroObject, property: &'static StyledProperty<T>) {
        let metadata = property.get_metadata_for(owner);
        let Some(coercion) = metadata.coercion() else { return };
        // Retain this exact metadata Rc through application and cleanup.
        // The factory separately reloads metadata at the original point.
        coercion.coerce_default(
            &metadata,
            owner,
            &CoercedDefaultFactory { store: self, owner, property },
            DefaultCoercionOperations {
                // This route originally used PartialEq, not value_equals:
                // preserve its distinct NaN behavior.
                equals: <T as PartialEq>::eq,
                set_default: EffectiveValue::<T>::set_coerced_default_value_and_raise,
            },
        );
    }

    pub fn get_base_value<T: PropertyValue>(&self, property: &'static StyledProperty<T>) -> Option<T> {
        let effective = self.get_effective_value(property)?;
        cast_effective_value::<T>(&*effective).try_get_base_value()
    }

    /// Finds the effective value of an inherited property on the nearest
    /// ancestor that has one.
    pub fn try_get_inherited_value(&self, property: &FerroProperty) -> Option<EffectiveValueRef> {
        debug_assert!(property.inherits());
        let mut current = self.inheritance_ancestor();
        while let Some(ancestor) = current {
            let store = ancestor.values();
            if let Some(v) = store.get_effective_value(property) {
                return Some(v);
            }
            let next = store.inheritance_ancestor();
            // A store that holds inherited values is its own ancestor marker;
            // never loop on it.
            current = match next {
                Some(n) if n.ptr_eq(&ancestor) => None,
                other => other,
            };
        }
        None
    }

    pub fn create_effective_value<T: PropertyValue>(
        &self,
        owner: &FerroObject,
        property: &'static StyledProperty<T>,
    ) -> Rc<EffectiveValue<T>> {
        let inherited = if property.inherits() { self.try_get_inherited_value(property) } else { None };
        let inherited = inherited.as_deref().map(cast_effective_value::<T>);
        Rc::new(EffectiveValue::new(owner, property, inherited))
    }

    /// The ancestor store to use for inherited value lookups starting at
    /// `object`: the object itself if it holds inherited values, otherwise its
    /// own ancestor.
    fn ancestor_for(object: &Ref<FerroObject>) -> Option<Ref<FerroObject>> {
        if object.values().inherited_value_count.get() == 0 {
            object.values().parent_ancestor()
        } else {
            Some(object.clone())
        }
    }

    /// The inheritance ancestor excluding the owner itself.
    fn parent_ancestor(&self) -> Option<Ref<FerroObject>> {
        self.inheritance_ancestor()
    }

    pub fn set_inheritance_parent(&self, owner: &FerroObject, new_parent: Option<&Ref<FerroObject>>) {
        let old_ancestor = self.inheritance_ancestor();
        let new_ancestor = new_parent.and_then(Self::ancestor_for);

        // The old and new inheritance ancestors are the same, nothing to do.
        let same = match (&old_ancestor, &new_ancestor) {
            (Some(a), Some(b)) => a.ptr_eq(b),
            (None, None) => true,
            _ => false,
        };
        if same {
            return;
        }
        crate::perf_count!(InheritanceAncestorChanges);

        // A list of the pool. The pool is not there any more while the
        // thread is torn down: a new list serves then.
        let mut values: Vec<OldNewValue> =
            OLD_NEW_VALUES_POOL.try_with(|pool| pool.borrow_mut().pop()).ok().flatten().unwrap_or_default();

        fn collect(
            start: Option<Ref<FerroObject>>,
            mut visit: impl FnMut(&'static FerroProperty, &EffectiveValueRef),
        ) {
            let mut current = start;
            while let Some(ancestor) = current {
                for (_, value) in ancestor.values().effective_values.borrow().iter() {
                    if value.property().inherits() {
                        visit(value.property(), value);
                    }
                }
                current = ancestor.values().parent_ancestor_of(&ancestor);
            }
        }

        // First get the old values from the old inheritance ancestor.
        collect(old_ancestor, |property, value| {
            if !values.iter().any(|v| v.property.id() == property.id()) {
                values.push(OldNewValue { property, old: Some(value.clone()), new: None });
            }
        });

        // Get the new values from the new inheritance ancestor.
        collect(new_ancestor.clone(), |property, value| {
            match values.iter_mut().find(|v| v.property.id() == property.id()) {
                Some(existing) => {
                    if existing.new.is_none() {
                        existing.new = Some(value.clone());
                    }
                }
                None => values.push(OldNewValue { property, old: None, new: Some(value.clone()) }),
            }
        });

        self.on_inheritance_ancestor_changed(owner, new_ancestor.as_ref());

        // Raise PropertyChanged events where necessary on this object and
        // inheritance children. Each pair leaves the list as its turn comes,
        // in the order it was added, and the pairs after it stay in the list
        // until theirs.
        //
        // Deviation (DEVIATIONS.md, Property system): the dictionary of the
        // original is sorted by property ID, so it raises the properties in
        // the order of their IDs; this list is in the order the pairs were
        // found (the nearest old ancestor first, each store by property ID,
        // then the properties only the new ancestors hold). The two orders
        // are the same when all the values come from one store.
        for v in values.drain(..) {
            crate::perf_count!(InheritedValuesCompared);
            let same = match (&v.old, &v.new) {
                (Some(a), Some(b)) => std::ptr::addr_eq(Rc::as_ptr(a), Rc::as_ptr(b)),
                _ => false,
            };
            if !same {
                crate::perf_count!(InheritedValuesDiffering);
                self.inherited_value_changed(owner, v.property, v.old.as_deref(), v.new.as_deref());
            }
        }

        // Give the list, now empty, back to the pool.
        let _ = OLD_NEW_VALUES_POOL.try_with(|pool| {
            let mut pool = pool.borrow_mut();
            if pool.len() < MAX_OLD_NEW_VALUES_POOL_SIZE {
                pool.push(values);
            }
        });
    }

    /// The next ancestor up the chain from `this_object`'s store, skipping the
    /// self-marker.
    fn parent_ancestor_of(&self, this_object: &Ref<FerroObject>) -> Option<Ref<FerroObject>> {
        match self.inheritance_ancestor() {
            Some(a) if a.ptr_eq(this_object) => {
                // This store is its own marker; continue from the owner's parent.
                this_object.inheritance_parent().and_then(|p| Self::ancestor_for(&p))
            }
            other => other,
        }
    }

    pub fn on_binding_value_changed(&self, owner: &FerroObject, entry: &Rc<dyn IValueEntry>, priority: BindingPriority) {
        debug_assert!(priority != BindingPriority::LocalValue);
        let property = entry.property();
        match self.get_effective_value(property) {
            Some(existing) => {
                if priority <= existing.base_priority() {
                    self.reevaluate_effective_value(owner, property, Some(existing), Some(entry), false);
                }
            }
            None => self.add_effective_value_and_raise(owner, property, entry, priority),
        }
    }

    pub fn on_frame_activation_changed(&self, owner: &FerroObject, frame: &Rc<dyn ValueFrame>) {
        match frame.base().entry_count() {
            0 => {}
            1 => {
                let property = frame.base().get_entry(0).property();
                let current = self.get_effective_value(property);
                self.reevaluate_effective_value(owner, property, current, None, false);
            }
            _ => self.reevaluate_effective_values(owner, None),
        }
    }

    /// Called when the nearest ancestor holding inherited values changes.
    /// `ancestor` is the new ancestor for the owner's children when the owner
    /// holds no inherited values itself.
    pub fn on_inheritance_ancestor_changed(&self, owner: &FerroObject, ancestor: Option<&Ref<FerroObject>>) {
        let is_self = ancestor.is_some_and(|a| {
            let a: &FerroObject = a;
            std::ptr::eq(a, owner)
        });
        if !is_self {
            *self.inheritance_ancestor.borrow_mut() = ancestor.map(Ref::downgrade);
            if self.inherited_value_count.get() > 0 {
                return;
            }
        }
        owner.for_each_inheritance_child(|child| {
            child.values().on_inheritance_ancestor_changed(child, ancestor);
        });
    }

    pub fn on_inherited_effective_value_changed(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        old_value: &dyn Any,
        new_value: &dyn Any,
    ) {
        debug_assert!(property.inherits());
        owner.for_each_inheritance_child(|child| {
            child.values().on_ancestor_inherited_value_changed(child, property, old_value, new_value);
        });
    }

    pub fn on_local_value_binding_completed(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        observer: &dyn IDisposable,
    ) {
        let removed = {
            let mut bindings = self.local_value_bindings.borrow_mut();
            match bindings.iter().position(|(id, _)| *id == property.id()) {
                Some(index) if std::ptr::addr_eq(Rc::as_ptr(&bindings[index].1), std::ptr::from_ref(observer)) => {
                    bindings.remove(index);
                    self.local_value_expressions.borrow_mut().retain(|(id, _)| *id != property.id());
                    true
                }
                _ => false,
            }
        };
        if removed {
            self.clear_value(owner, property);
        }
    }

    fn on_ancestor_inherited_value_changed(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        old_value: &dyn Any,
        new_value: &dyn Any,
    ) {
        // If the inherited value is set locally, propagation stops here.
        if self.is_set(property) {
            return;
        }
        let notifying = property.notifying();
        if let Some(notifying) = notifying {
            notifying(owner, true);
        }
        owner.raise_inherited_property_changed(property, old_value, new_value, BindingPriority::Inherited);
        owner.for_each_inheritance_child(|child| {
            child.values().on_ancestor_inherited_value_changed(child, property, old_value, new_value);
        });
        if let Some(notifying) = notifying {
            notifying(owner, false);
        }
    }

    pub fn on_value_entry_removed(&self, owner: &FerroObject, frame: &Rc<dyn ValueFrame>, property: &'static FerroProperty) {
        if frame.base().entry_count() == 0 {
            let mut frames = self.frames.borrow_mut();
            if let Some(index) = frames.iter().position(|f| frame_ptr_eq(f, frame)) {
                frames.remove(index);
            }
        }
        if let Some(existing) = self.get_effective_value(property) {
            if frame.base().priority() <= existing.priority() {
                self.reevaluate_effective_value(owner, property, Some(existing), None, false);
            }
        }
    }

    pub fn remove_frame(&self, owner: &FerroObject, frame: &Rc<dyn ValueFrame>) -> bool {
        let removed = {
            let mut frames = self.frames.borrow_mut();
            frames.iter().position(|f| frame_ptr_eq(f, frame)).map(|i| frames.remove(i))
        };
        match removed {
            Some(frame) => {
                frame.dispose();
                self.frame_generation.set(self.frame_generation.get().wrapping_add(1));
                self.reevaluate_effective_values(owner, None);
                true
            }
            None => false,
        }
    }

    /// Removes all style/theme frames of the given type (immediate value
    /// frames are kept).
    pub fn remove_frames(&self, owner: &FerroObject, type_: FrameType) {
        self.remove_frames_where(owner, |frame| {
            !frame.as_any().is::<ImmediateValueFrame>() && frame.base().frame_priority().is_type(type_)
        });
    }

    /// Removes all frames matching `predicate`.
    pub fn remove_frames_where(&self, owner: &FerroObject, predicate: impl Fn(&Rc<dyn ValueFrame>) -> bool) {
        let removed: Vec<Rc<dyn ValueFrame>> = {
            let mut frames = self.frames.borrow_mut();
            let mut removed = Vec::new();
            let mut i = frames.len();
            while i > 0 {
                i -= 1;
                if predicate(&frames[i]) {
                    removed.push(frames.remove(i));
                }
            }
            removed
        };
        if !removed.is_empty() {
            for frame in &removed {
                frame.dispose();
            }
            self.frame_generation.set(self.frame_generation.get().wrapping_add(1));
            self.reevaluate_effective_values(owner, None);
        }
    }

    /// The priority the property's effective value currently has.
    pub fn get_priority(&self, property: &FerroProperty) -> BindingPriority {
        match self.get_effective_value(property) {
            Some(v) => v.priority(),
            None if property.inherits() && self.try_get_inherited_value(property).is_some() => {
                BindingPriority::Inherited
            }
            None => BindingPriority::Unset,
        }
    }

    fn insert_frame(&self, owner: &FerroObject, frame: Rc<dyn ValueFrame>) -> usize {
        debug_assert!(!self.frames.borrow().iter().any(|f| frame_ptr_eq(f, &frame)));
        let index = self.binary_search_frame(frame.base().frame_priority());
        frame.base().set_owner(Some(owner.to_weak()));
        self.frames.borrow_mut().insert(index, frame);
        self.frame_generation.set(self.frame_generation.get().wrapping_add(1));
        index
    }

    fn get_or_create_immediate_value_frame(
        &self,
        owner: &FerroObject,
        property: &FerroProperty,
        priority: BindingPriority,
    ) -> Rc<ImmediateValueFrame> {
        debug_assert!(priority != BindingPriority::LocalValue);
        let index = self.binary_search_frame(FramePriority::new(priority, FrameType::Style));
        if index > 0 {
            let frames = self.frames.borrow();
            let candidate = &frames[index - 1];
            if candidate.base().priority() == priority && !candidate.base().contains(property) {
                let any: Rc<dyn std::any::Any> = candidate.clone();
                if let Ok(frame) = any.downcast::<ImmediateValueFrame>() {
                    return frame;
                }
            }
        }
        let result = ImmediateValueFrame::new(priority);
        self.insert_frame(owner, result.clone());
        result
    }

    fn get_or_add_effective_value(&self, owner: &FerroObject, property: &'static FerroProperty) -> EffectiveValueRef {
        match self.get_effective_value(property) {
            Some(existing) => existing,
            None => self.create_and_add_effective_value(owner, property),
        }
    }

    // The construction route preserves the property's Rust type. Only a miss
    // needs this dispatch; lookup and insertion are the same for every type.
    fn create_and_add_effective_value(&self, owner: &FerroObject, property: &'static FerroProperty) -> EffectiveValueRef {
        let value = property.routes().create_effective_value(owner);
        self.add_effective_value(owner, property, value.clone());
        value
    }

    fn add_effective_value(&self, owner: &FerroObject, property: &FerroProperty, value: EffectiveValueRef) {
        {
            let mut values = self.effective_values.borrow_mut();
            if values.capacity() == 0 {
                // A control holds several values once styled: room for them in one allocation
                // instead of growing through four.
                values.reserve_exact(8);
            }
            let index = values.partition_point(|(id, _)| *id < property.id());
            debug_assert!(values.get(index).is_none_or(|(id, _)| *id != property.id()));
            values.insert(index, (property.id(), value));
        }
        if property.inherits() {
            let count = self.inherited_value_count.get();
            self.inherited_value_count.set(count + 1);
            if count == 0 {
                self.on_inheritance_ancestor_changed(owner, Some(&owner.to_ref()));
            }
        }
    }

    fn add_effective_value_and_raise(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        entry: &Rc<dyn IValueEntry>,
        priority: BindingPriority,
    ) {
        debug_assert!(priority < BindingPriority::Inherited);
        let effective = self.create_and_add_effective_value(owner, property);
        effective.set_and_raise(owner, entry, priority);
    }

    fn remove_effective_value(&self, owner: &FerroObject, property: &FerroProperty) -> bool {
        let removed = {
            let mut values = self.effective_values.borrow_mut();
            Self::find(&values, property.id()).map(|index| values.remove(index))
        };
        if removed.is_none() {
            return false;
        }
        if property.inherits() {
            let count = self.inherited_value_count.get() - 1;
            self.inherited_value_count.set(count);
            if count == 0 {
                let ancestor = owner.inheritance_parent().and_then(|p| Self::ancestor_for(&p));
                // Detach the self-marker first so the notification is not
                // mistaken for "the owner is the ancestor".
                *self.inheritance_ancestor.borrow_mut() = ancestor.as_ref().map(Ref::downgrade);
                owner.for_each_inheritance_child(|child| {
                    child.values().on_inheritance_ancestor_changed(child, ancestor.as_ref());
                });
            }
        }
        true
    }

    fn inherited_value_changed(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        old_value: Option<&dyn EffectiveValueDyn>,
        new_value: Option<&dyn EffectiveValueDyn>,
    ) {
        debug_assert!(old_value.is_some() || new_value.is_some());
        crate::perf_count!(InheritedValueWalkVisits);

        // If the value is set locally, propagation ends here.
        if self.is_set(property) {
            return;
        }

        let notifying = property.notifying();
        if let Some(notifying) = notifying {
            notifying(owner, true);
        }

        // Raise PropertyChanged on this object if necessary.
        let raiser = old_value.or(new_value).expect("one of the values is set");
        raiser.raise_inherited_value_changed(property, owner, old_value, new_value);

        owner.for_each_inheritance_child(|child| {
            child.values().inherited_value_changed(child, property, old_value, new_value)
        });

        if let Some(notifying) = notifying {
            notifying(owner, false);
        }
    }

    fn reevaluate_effective_value(
        &self,
        owner: &FerroObject,
        property: &'static FerroProperty,
        mut current: Option<EffectiveValueRef>,
        changed_value_entry: Option<&Rc<dyn IValueEntry>>,
        ignore_local_value: bool,
    ) {
        self.is_evaluating.set(self.is_evaluating.get() + 1);
        let _guard = EvaluatingGuard(&self.is_evaluating);

        'restart: loop {
            // Don't reevaluate if a styling pass is in effect, reevaluation
            // will be done when it has finished.
            if self.styling.get() > 0 {
                return;
            }

            let generation = self.frame_generation.get();

            // Notify the existing effective value that reevaluation is starting.
            if let Some(current) = &current {
                current.begin_reevaluation(ignore_local_value);
            }

            // Iterate the frames to get the effective value.
            let mut index = self.frames.borrow().len();
            while index > 0 {
                index -= 1;
                let frame = self.frame_at(index);
                let priority = frame.base().priority();

                // Exit early if the current effective value has higher priority
                // than this frame.
                if let Some(current) = &current {
                    if current.priority() < priority && current.base_priority() < priority {
                        break;
                    }
                }

                // Try to get an entry from the frame for the property.
                let (entry, active_changed) = frame.try_get_entry_if_active(property);

                // If the active state of the frame has changed since the last
                // read, and the frame holds multiple values then we need to
                // re-evaluate the effective values of all properties.
                if active_changed && frame.base().entry_count() > 1 {
                    self.reevaluate_effective_values(owner, changed_value_entry);
                    return;
                }

                // If the frame has an entry for this property with a higher
                // priority than the current effective value (and that entry has
                // a value), then we have a new value for the property. The
                // check for `has_value` must be evaluated last as it can cause
                // bindings to be subscribed.
                if let Some(entry) = entry {
                    if Self::has_higher_priority(&entry, priority, current.as_deref(), changed_value_entry)
                        && entry.has_value()
                    {
                        match &current {
                            Some(current) => current.set_and_raise(owner, &entry, priority),
                            None => {
                                let created = self.create_and_add_effective_value(owner, property);
                                created.set_and_raise(owner, &entry, priority);
                                current = Some(created);
                            }
                        }
                    }
                }

                if generation != self.frame_generation.get() {
                    continue 'restart;
                }
            }

            if let Some(current) = &current {
                current.end_reevaluation(owner);

                if current.can_remove() {
                    if current.base_priority() == BindingPriority::Unset {
                        self.remove_effective_value(owner, property);
                        current.dispose_and_raise_unset(owner);
                    } else {
                        current.remove_animation_and_raise(owner);
                    }
                }

                current.unsubscribe_if_necessary();
            }
            return;
        }
    }

    fn reevaluate_effective_values(&self, owner: &FerroObject, changed_value_entry: Option<&Rc<dyn IValueEntry>>) {
        self.is_evaluating.set(self.is_evaluating.get() + 1);
        let _guard = EvaluatingGuard(&self.is_evaluating);

        'restart: loop {
            // Don't reevaluate if a styling pass is in effect, reevaluation
            // will be done when it has finished.
            if self.styling.get() > 0 {
                return;
            }

            let generation = self.frame_generation.get();

            // Notify the existing effective values that reevaluation is
            // starting. They are visited in place, as the original indexes
            // its list: `begin_reevaluation` only resets the priorities the
            // value records and calls nothing that could reach the store, so
            // no copy of the list is needed for the visit.
            for (_, value) in self.effective_values.borrow().iter() {
                value.begin_reevaluation(false);
            }

            // Iterate the frames, setting and creating effective values.
            let mut index = self.frames.borrow().len();
            while index > 0 {
                index -= 1;
                let frame = self.frame_at(index);
                if !frame.is_active() {
                    continue;
                }

                let priority = frame.base().priority();
                let count = frame.base().entry_count();

                for j in 0..count {
                    if j >= frame.base().entry_count() {
                        break;
                    }
                    let entry = frame.base().get_entry(j);
                    let property = entry.property();
                    let effective = self.get_effective_value(property);

                    if !Self::has_higher_priority(&entry, priority, effective.as_deref(), changed_value_entry) {
                        continue;
                    }
                    if !entry.has_value() {
                        continue;
                    }

                    match effective {
                        Some(effective) => effective.set_and_raise(owner, &entry, priority),
                        None => {
                            self.add_effective_value_and_raise(owner, property, &entry, priority);
                        }
                    }

                    if generation != self.frame_generation.get() {
                        continue 'restart;
                    }
                }
            }

            // Remove all effective values that are still unset.
            let mut values = REEVALUATION_LISTS.with(|lists| lists.borrow_mut().pop()).unwrap_or_default();
            values.extend(self.effective_values.borrow().iter().map(|(_, v)| v.clone()));
            for value in values.iter().rev() {
                let property = value.property();
                value.end_reevaluation(owner);
                if value.can_remove() {
                    self.remove_effective_value(owner, property);
                    value.dispose_and_raise_unset(owner);
                }
                value.unsubscribe_if_necessary();
            }
            values.clear();
            if values.capacity() <= 64 {
                REEVALUATION_LISTS.with(|lists| lists.borrow_mut().push(values));
            }
            return;
        }
    }

    fn has_higher_priority(
        entry: &Rc<dyn IValueEntry>,
        entry_priority: BindingPriority,
        current: Option<&dyn EffectiveValueDyn>,
        changed_value_entry: Option<&Rc<dyn IValueEntry>>,
    ) -> bool {
        // Set the value if: there is no current effective value; or
        let Some(current) = current else { return true };

        // The value's priority is higher than the current effective value's
        // priority; or
        if entry_priority < current.priority() && entry_priority < current.base_priority() {
            return true;
        }

        // - The value's priority is equal to the current effective value's priority
        // - But the effective value was set via SetCurrentValue
        // - As long as the SetCurrentValue wasn't overriding the value from the
        //   value entry under consideration
        // - Or if it was, the value entry under consideration has changed; or
        if entry_priority == current.priority() && current.is_overriden_current_value() {
            let is_current_entry = current.value_entry().is_some_and(|e| entry_ptr_eq(&e, entry));
            let is_changed_entry = changed_value_entry.is_some_and(|e| entry_ptr_eq(e, entry));
            if !is_current_entry || is_changed_entry {
                return true;
            }
        }

        // The value is a non-animation value and its priority is higher than
        // the current effective value's base priority.
        entry_priority > BindingPriority::Animation && entry_priority < current.base_priority()
    }

    #[inline]
    fn find(values: &[(u32, EffectiveValueRef)], id: u32) -> Option<usize> {
        // Objects typically hold a handful of values: a linear scan over the
        // sorted IDs beats a binary search at these sizes.
        if values.len() <= 8 {
            values.iter().position(|(i, _)| *i == id)
        } else {
            values.binary_search_by_key(&id, |(i, _)| *i).ok()
        }
    }

    #[inline]
    pub fn get_effective_value(&self, property: &FerroProperty) -> Option<EffectiveValueRef> {
        let values = self.effective_values.borrow();
        Self::find(&values, property.id()).map(|index| values[index].1.clone())
    }

    /// The diagnostic of the store: its effective values of local value
    /// priority as one frame, followed by a diagnostic of each frame.
    pub fn get_store_diagnostic(&self) -> ValueStoreDiagnostic {
        let mut frames: Vec<Rc<dyn IValueFrameDiagnostic>> = Vec::new();

        let effective_values: Vec<EffectiveValueRef> =
            self.effective_values.borrow().iter().map(|(_, value)| value.clone()).collect();
        let mut effective_local_values = Vec::with_capacity(effective_values.len());
        for effective_value in effective_values {
            if effective_value.priority() == BindingPriority::LocalValue {
                effective_local_values
                    .push(ValueEntryDiagnostic::new(effective_value.property(), Some(effective_value.boxed_value())));
            }
        }

        if !effective_local_values.is_empty() {
            frames.push(Rc::new(LocalValueFrameDiagnostic::new(effective_local_values)));
        }

        for frame in self.frames() {
            match StyleValueFrameDiagnostic::new(&frame) {
                Some(style_frame) => frames.push(Rc::new(style_frame)),
                None => frames.push(Rc::new(ValueFrameDiagnostic::new(frame))),
            }
        }

        ValueStoreDiagnostic::new(frames)
    }

    fn set_local_value_binding(&self, property: &FerroProperty, binding: Rc<dyn IDisposable>) {
        #[cfg(all(debug_assertions, feature = "hot-reload"))]
        self.record_local_write(property);
        // The slot is being taken over: a binding expression that held it is
        // no longer the property's local value binding.
        self.local_value_expressions.borrow_mut().retain(|(id, _)| *id != property.id());
        let mut bindings = self.local_value_bindings.borrow_mut();
        match bindings.iter_mut().find(|(id, _)| *id == property.id()) {
            Some(slot) => slot.1 = binding,
            None => bindings.push((property.id(), binding)),
        }
    }

    fn dispose_existing_local_value_binding(&self, property: &FerroProperty) {
        let existing =
            self.local_value_bindings.borrow().iter().find(|(id, _)| *id == property.id()).map(|(_, b)| b.clone());
        if let Some(existing) = existing {
            existing.dispose();
        }
    }

    fn binary_search_frame(&self, priority: FramePriority) -> usize {
        // Insertion point: after all frames with a priority value greater than
        // or equal to `priority` (the list runs from lowest to highest
        // precedence, i.e. descending priority value).
        self.frames.borrow().partition_point(|f| priority <= f.base().frame_priority())
    }
}

struct EvaluatingGuard<'a>(&'a Cell<u32>);

impl Drop for EvaluatingGuard<'_> {
    fn drop(&mut self) {
        self.0.set(self.0.get() - 1);
    }
}

#[cfg(test)]
#[path = "value_store_default_coercion_tests.rs"]
mod default_coercion_tests;

//! Keep the original metadata guard, owned values and effective-value local
//! observable across coercion, metadata replacement, creation and cleanup.

use super::*;
use crate::{FerroObjectImpl, Ref, StaticType, StyledPropertyMetadata, StyledPropertyOptions};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::rc::Weak;
use std::sync::atomic::{AtomicUsize, Ordering};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Operation { Clone, Equals, Coerce, Notify, Drop, CallbackDrop }

impl Operation {
    const ALL: [Self; 6] = [Self::Clone, Self::Equals, Self::Coerce, Self::Notify, Self::Drop, Self::CallbackDrop];
}

#[derive(Clone, Copy, Debug)]
enum Action { Panic, Read, Write, RemoveEntry }

#[derive(Clone, Copy, Debug)]
struct Injection {
    operation: Operation,
    occurrence: usize,
    action: Action,
}

struct Trace {
    active: Cell<bool>,
    next: Cell<usize>,
    counts: [Cell<usize>; 6],
    events: RefCell<Vec<String>>,
    injection: Cell<Option<Injection>>,
    fired: Cell<bool>,
    replacement_at: Cell<Option<Operation>>,
    replaced: Cell<bool>,
    owner: WeakRef<FerroObject>,
    property: Cell<Option<&'static StyledProperty<Tracked>>>,
    original_metadata: RefCell<Option<Weak<StyledPropertyMetadata<Tracked>>>>,
    entry: RefCell<Option<Weak<dyn EffectiveValueDyn>>>,
}

impl Trace {
    fn value(self: &Rc<Self>, number: i32) -> Tracked {
        let serial = self.next.get();
        self.next.set(serial + 1);
        Tracked { number, serial, trace: self.clone() }
    }

    fn record(self: &Rc<Self>, operation: Operation, detail: String) {
        if !self.active.get() { return; }
        // Weak observations do not create an extra owning guard that could
        // hide a metadata or returned-effective-value lifetime regression.
        let metadata_count = self.original_metadata.borrow().as_ref().map_or(0, Weak::strong_count);
        let entry_count = self.entry.borrow().as_ref().map_or(0, Weak::strong_count);
        self.events.borrow_mut().push(format!("{operation:?}:{detail}; metadata={metadata_count}; entry={entry_count}"));
        let count = &self.counts[operation as usize];
        let occurrence = count.get() + 1;
        count.set(occurrence);
        if self.replacement_at.get() == Some(operation) {
            self.replacement_at.set(None);
            self.replace_metadata();
        }
        let Some(injection) = self.injection.get() else { return };
        if injection.operation != operation || injection.occurrence != occurrence { return; }
        // Disarm before any reentry or destructor panic.
        self.injection.set(None);
        self.fired.set(true);
        self.events.borrow_mut().push(format!("inject:{:?}", injection.action));
        if let Action::Panic = injection.action { panic!("injected default-coercion operation panic"); }
        let owner = self.owner.upgrade().unwrap();
        let property = self.property.get().unwrap();
        match injection.action {
            Action::Read => drop(owner.get_value(property)),
            Action::Write => owner.set_value(property, self.value(90)),
            Action::RemoveEntry => {
                // Exercise the real store removal during publication. The
                // factory's returned Rc must remain its sole surviving owner
                // until the setter returns, then drop before default/metadata.
                assert!(owner.values().remove_effective_value(&owner, property));
            }
            Action::Panic => unreachable!(),
        }
    }

    fn replace_metadata(self: &Rc<Self>) {
        assert!(!self.replaced.replace(true));
        let property = self.property.get().unwrap();
        // Overrides are immutable registrations: replacing one requires the
        // existing public unregister operation before registering its successor.
        property.unregister(CoercionOwner::TYPE);
        property.override_metadata::<CoercionOwner>(
            StyledPropertyMetadata::new(Some(self.value(50))).with_coerce(coercer(self.clone(), 100, "replacement")),
        );
    }

    fn capture_entry(&self, owner: &FerroObject) {
        if !self.active.get() { return; }
        if let Some(entry) = owner.values().get_effective_value(self.property.get().unwrap()) {
            *self.entry.borrow_mut() = Some(Rc::downgrade(&entry));
        }
    }
}

struct Tracked {
    number: i32,
    serial: usize,
    trace: Rc<Trace>,
}

impl Clone for Tracked {
    fn clone(&self) -> Self {
        self.trace.record(Operation::Clone, format!("{}={}", self.serial, self.number));
        self.trace.value(self.number)
    }
}

impl PartialEq for Tracked {
    fn eq(&self, other: &Self) -> bool {
        self.trace.record(Operation::Equals, format!("{}={} / {}={}", self.serial, self.number, other.serial, other.number));
        self.number == other.number
    }
}

impl Drop for Tracked {
    fn drop(&mut self) { self.trace.record(Operation::Drop, format!("{}={}", self.serial, self.number)); }
}

struct CallbackLife {
    trace: Rc<Trace>,
    name: &'static str,
}

impl Drop for CallbackLife {
    fn drop(&mut self) { self.trace.record(Operation::CallbackDrop, self.name.to_string()); }
}

fn coercer(trace: Rc<Trace>, delta: i32, name: &'static str) -> impl Fn(&FerroObject, Tracked) -> Tracked {
    let life = CallbackLife { trace: trace.clone(), name };
    move |_: &FerroObject, mut value: Tracked| {
        let _retain_whole_capture = &life;
        trace.record(Operation::Coerce, format!("{name}:{}={}", value.serial, value.number));
        value.number += delta;
        value
    }
}

#[repr(C)]
struct CoercionOwner { base: FerroObject }
crate::ferro_class!(CoercionOwner: FerroObject);
crate::ferro_impl_classes!(CoercionOwner: FerroObjectImpl);

impl CoercionOwner {
    fn new() -> Ref<Self> { crate::instantiate(Self { base: FerroObject::construct() }) }
}

fn unique_name() -> String {
    static NEXT: AtomicUsize = AtomicUsize::new(0);
    format!("DemandRootedDefault{}", NEXT.fetch_add(1, Ordering::Relaxed))
}

#[derive(Debug, PartialEq, Eq)]
struct Outcome {
    panicked: bool,
    fired: bool,
    replaced: bool,
    counts: [usize; 6],
    events: Vec<String>,
    value: Option<i32>,
    after_write: Option<i32>,
    original_metadata_alive: bool,
    entry_owners: usize,
}

fn run(original: bool, delta: i32, replacement_at: Option<Operation>, injection: Option<Injection>) -> Outcome {
    let concrete = CoercionOwner::new();
    let owner: &FerroObject = &concrete;
    let trace = Rc::new(Trace {
        active: Cell::new(false), next: Cell::new(0),
        counts: std::array::from_fn(|_| Cell::new(0)), events: RefCell::new(Vec::new()),
        injection: Cell::new(injection), fired: Cell::new(false), replacement_at: Cell::new(replacement_at),
        replaced: Cell::new(false), owner: owner.to_ref().downgrade(), property: Cell::new(None),
        original_metadata: RefCell::new(None), entry: RefCell::new(None),
    });
    let notifying = trace.clone();
    let property = FerroProperty::register_with::<FerroObject, _>(
        &unique_name(), StyledPropertyOptions::new(trace.value(1)).notifying(move |owner, before| {
            if before { notifying.capture_entry(owner); }
            notifying.record(Operation::Notify, before.to_string());
        }),
    );
    trace.property.set(Some(property));
    // Use a replaceable derived-owner override, not the immutable declaring
    // owner's metadata. No test Rc is kept alive across the operation.
    property.override_metadata::<CoercionOwner>(
        StyledPropertyMetadata::new(Some(trace.value(5))).with_coerce(coercer(trace.clone(), delta, "original")),
    );
    let metadata = property.get_metadata_for(owner);
    *trace.original_metadata.borrow_mut() = Some(Rc::downgrade(&metadata));
    drop(metadata);
    trace.active.set(true);
    let panicked = catch_unwind(AssertUnwindSafe(|| {
        if original { owner.values().original_coerce_default_value(owner, property); }
        else { owner.values().coerce_default_value(owner, property); }
    })).is_err();
    trace.active.set(false);
    let value = owner.values().get_effective_value(property).map(|entry| cast_effective_value::<Tracked>(&*entry).value().number);
    let original_metadata_alive = trace.original_metadata.borrow().as_ref().unwrap().strong_count() != 0;
    let entry_owners = trace.entry.borrow().as_ref().map_or(0, Weak::strong_count);
    // A subsequent ordinary write proves which metadata the factory retained.
    // It is outside the trace and is never attempted after a partial unwind.
    let after_write = if !panicked && value.is_some() {
        owner.set_value(property, trace.value(3));
        Some(owner.get_value(property).number)
    } else { None };
    let events = std::mem::take(&mut *trace.events.borrow_mut());
    Outcome {
        panicked, fired: trace.fired.get(), replaced: trace.replaced.get(),
        counts: std::array::from_fn(|i| trace.counts[i].get()), events, value, after_write,
        original_metadata_alive, entry_owners,
    }
}

#[test]
fn default_coercion_matches_original_metadata_values_factory_and_unwind() {
    for delta in [0, 1] {
        for replacement_at in [None, Some(Operation::Coerce), Some(Operation::Equals)] {
            let baseline = run(true, delta, replacement_at, None);
            assert!(!baseline.panicked);
            assert_eq!(run(false, delta, replacement_at, None), baseline);
            for operation in Operation::ALL {
                for occurrence in 1..=baseline.counts[operation as usize] {
                    let injection = Some(Injection { operation, occurrence, action: Action::Panic });
                    let expected = run(true, delta, replacement_at, injection);
                    assert!(expected.panicked && expected.fired, "{operation:?}:{occurrence}");
                    assert_eq!(run(false, delta, replacement_at, injection), expected,
                        "delta={delta}, replacement={replacement_at:?}, {injection:?}");
                }
            }
        }
    }
}

#[test]
fn default_coercion_keeps_metadata_reload_and_returned_entry_cleanup_during_reentry() {
    for replacement_at in [Some(Operation::Coerce), Some(Operation::Equals)] {
        let expected = run(true, 1, replacement_at, None);
        assert!(expected.replaced && !expected.original_metadata_alive);
        assert_eq!((expected.value, expected.after_write), (Some(6), Some(103)));
        assert_eq!(expected.counts[Operation::CallbackDrop as usize], 1);
        assert_eq!(run(false, 1, replacement_at, None), expected);
    }
    let baseline = run(true, 1, None, None);
    let mut injections = vec![
        Injection { operation: Operation::Clone, occurrence: 1, action: Action::Read },
        Injection { operation: Operation::Equals, occurrence: 1, action: Action::Read },
        Injection { operation: Operation::Coerce, occurrence: 1, action: Action::Write },
        Injection { operation: Operation::Equals, occurrence: 1, action: Action::Write },
        Injection { operation: Operation::Notify, occurrence: 1, action: Action::RemoveEntry },
    ];
    injections.extend((1..=baseline.counts[Operation::Drop as usize]).map(|occurrence| {
        Injection { operation: Operation::Drop, occurrence, action: Action::Read }
    }));
    for injection in injections {
        let expected = run(true, 1, None, Some(injection));
        assert!(expected.fired, "{injection:?}");
        if matches!(injection.action, Action::Write) && cfg!(debug_assertions) {
            assert!(expected.panicked, "the reentrant write must reach the original duplicate-insertion assertion");
        }
        if matches!(injection.action, Action::RemoveEntry) {
            assert!(!expected.panicked);
            assert_eq!((expected.value, expected.entry_owners), (None, 0));
        }
        assert_eq!(run(false, 1, None, Some(injection)), expected, "{injection:?}");
    }
}

#[test]
fn default_coercion_retains_partial_eq_nan_and_absent_callback_behavior() {
    assert!(!std::mem::needs_drop::<CoercedDefaultFactory<'_, Tracked>>());
    for original in [false, true] {
        let owner = FerroObject::new();
        for (default, with_coercer, creates_entry) in [(1.0, false, false), (1.0, true, false), (f64::NAN, true, true)] {
            let mut options = StyledPropertyOptions::new(default);
            if with_coercer { options = options.coerce(|_, value| value); }
            let property = FerroProperty::register_with::<FerroObject, _>(&unique_name(), options);
            if original { owner.values().original_coerce_default_value(&owner, property); }
            else { owner.values().coerce_default_value(&owner, property); }
            let entry = owner.values().get_effective_value(property);
            assert_eq!(entry.is_some(), creates_entry);
            if let Some(entry) = entry {
                assert!(cast_effective_value::<f64>(&*entry).value().is_nan());
                assert!(!entry.can_remove());
            }
        }
    }
}

// Copied from bbff5971; only the oracle method name differs.
impl ValueStore {
    fn original_coerce_default_value<T: PropertyValue>(&self, owner: &FerroObject, property: &'static StyledProperty<T>) {
        let metadata = property.get_metadata_for(owner);
        let Some(coerce) = metadata.coerce_value() else { return };
        let default = metadata.default_value().clone();
        let coerced = coerce(owner, default.clone());
        if default == coerced {
            return;
        }
        // The default value isn't valid according to the coerce function, so
        // an effective value entry is needed.
        let effective = self.create_effective_value(owner, property);
        self.add_effective_value(owner, property, effective.clone());
        effective.set_coerced_default_value_and_raise(owner, coerced);
    }
}

use crate::data::{BindingError, BindingNotification, BindingPriority, BindingValue, BindingValueType};
use crate::ferro_property::{
    convert_property_value, copy_converted_property_value, FerroPropertyInit, NotifyingCallback, PropertyRoutes,
};
use crate::ferro_property_metadata::MetadataTable;
use crate::property_store::{EffectiveValueDyn, IValueEntry};
use crate::reactive::{IDisposable, IObservable};
use crate::{
    BoxedValue, ObjectType, DoNothingType, FerroObject, FerroProperty, FerroPropertyMetadata,
    FerroPropertyRegistry, PropertyValue, StyledPropertyMetadata, TypeInfo, UnsetValueType,
};
use std::any::Any;
use std::cell::RefCell;
use std::ops::Deref;
use std::rc::Rc;

/// A styled property: a property whose value is held by the property store
/// and can come from local values, styles, templates, animations, bindings and
/// inheritance, resolved by priority.
pub struct StyledProperty<T: PropertyValue> {
    base: FerroProperty,
    metadata: MetadataTable<StyledPropertyMetadata<T>>,
    /// For performance, the default value is cached while there is only one,
    /// avoiding a metadata lookup that may walk the class hierarchy.
    single_default_value: RefCell<Option<T>>,
    validate: Option<Box<dyn Fn(&T) -> bool>>,
}

impl<T: PropertyValue> Deref for StyledProperty<T> {
    type Target = FerroProperty;
    #[inline]
    fn deref(&self) -> &FerroProperty {
        &self.base
    }
}

impl<T: PropertyValue> StyledProperty<T> {
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn new(
        name: &str,
        owner_type: &'static TypeInfo,
        host_type: &'static TypeInfo,
        metadata: StyledPropertyMetadata<T>,
        inherits: bool,
        validate: Option<Box<dyn Fn(&T) -> bool>>,
        notifying: Option<NotifyingCallback>,
        is_attached: bool,
    ) -> Self {
        let default_value = metadata.default_value().clone();
        if let Some(validate) = &validate {
            if !validate(&default_value) {
                panic!("default value is not valid for property '{name}'");
            }
        }
        Self {
            base: FerroProperty::new::<T>(
                name,
                owner_type,
                FerroPropertyInit { inherits, is_attached, is_direct: false, is_read_only: false },
                notifying,
            ),
            metadata: MetadataTable::new(host_type, metadata),
            single_default_value: RefCell::new(Some(default_value)),
            validate,
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn create(
        name: &str,
        owner_type: &'static TypeInfo,
        host_type: &'static TypeInfo,
        metadata: StyledPropertyMetadata<T>,
        inherits: bool,
        validate: Option<Box<dyn Fn(&T) -> bool>>,
        notifying: Option<NotifyingCallback>,
        is_attached: bool,
    ) -> &'static Self {
        let property: &'static Self = Box::leak(Box::new(Self::new(
            name, owner_type, host_type, metadata, inherits, validate, notifying, is_attached,
        )));
        property.base.set_routes(property);
        property
    }

    /// The untyped base of the property.
    #[inline]
    pub fn as_property(&'static self) -> &'static FerroProperty {
        &self.base
    }

    /// The value validation callback for the property.
    #[inline]
    pub fn validate_value(&self) -> Option<&dyn Fn(&T) -> bool> {
        self.validate.as_deref()
    }

    #[inline]
    pub(crate) fn is_valid(&self, value: &T) -> bool {
        match &self.validate {
            Some(validate) => validate(value),
            None => true,
        }
    }

    /// Registers the property on another class.
    pub fn add_owner<TOwner: ObjectType>(&'static self) -> &'static Self {
        FerroPropertyRegistry::instance().register(TOwner::TYPE, self);
        self
    }

    /// Registers the property on another class, with metadata for that class.
    pub fn add_owner_with<TOwner: ObjectType>(&'static self, metadata: StyledPropertyMetadata<T>) -> &'static Self {
        FerroPropertyRegistry::instance().register(TOwner::TYPE, self);
        self.override_metadata::<TOwner>(metadata);
        self
    }

    /// Coerces `base_value` with the coercion callback registered for the
    /// type of `instance`, if any.
    pub fn coerce_value(&self, instance: &FerroObject, base_value: T) -> T {
        let metadata = self.get_metadata_for(instance);
        match metadata.coerce_value() {
            Some(coerce) => coerce(instance, base_value),
            None => base_value,
        }
    }

    /// Gets the default value for the property on the specified type.
    #[inline]
    pub fn get_default_value(&self, type_: &'static TypeInfo) -> T {
        self.default_for(|| type_)
    }

    /// Gets the default value for the property on the type of `owner`.
    #[inline]
    pub fn get_default_value_for(&self, owner: &FerroObject) -> T {
        self.default_for(|| owner.get_type())
    }

    #[inline]
    fn default_for(&self, host: impl FnOnce() -> &'static TypeInfo) -> T {
        if let Some(value) = &*self.single_default_value.borrow() {
            return value.clone();
        }
        self.get_metadata(host()).default_value().clone()
    }

    /// A binding keeps the first fallback it observes for its owner, even if
    /// the property's metadata is subsequently overridden.
    pub(crate) fn binding_default(&self, owner: &FerroObject, cache: &RefCell<Option<T>>) -> T {
        if let Some(value) = &*cache.borrow() {
            return value.clone();
        }
        let value = self.get_default_value_for(owner);
        *cache.borrow_mut() = Some(value.clone());
        value
    }

    /// Gets the property metadata for the specified type.
    #[inline]
    pub fn get_metadata(&self, type_: &'static TypeInfo) -> Rc<StyledPropertyMetadata<T>> {
        self.metadata.get(type_)
    }

    /// Gets the property metadata for the type of `owner`.
    #[inline]
    pub fn get_metadata_for(&self, owner: &FerroObject) -> Rc<StyledPropertyMetadata<T>> {
        self.metadata.get(owner.get_type())
    }

    /// Overrides the default value for the property on class `TOwner`.
    pub fn override_default_value<TOwner: ObjectType>(&self, default_value: T) {
        self.override_default_value_for(TOwner::TYPE, default_value);
    }

    /// Overrides the default value for the property on the specified type.
    pub fn override_default_value_for(&self, type_: &'static TypeInfo, default_value: T) {
        self.override_metadata_for(type_, StyledPropertyMetadata::new(Some(default_value)));
    }

    /// Overrides the metadata for the property on class `TOwner`.
    pub fn override_metadata<TOwner: ObjectType>(&self, metadata: StyledPropertyMetadata<T>) {
        self.override_metadata_for(TOwner::TYPE, metadata)
    }

    /// Overrides the metadata for the property on the specified type.
    pub fn override_metadata_for(&self, type_: &'static TypeInfo, metadata: StyledPropertyMetadata<T>) {
        if metadata.has_default_value() && !self.is_valid(metadata.default_value()) {
            panic!("default value is not valid for property '{}'", self.name());
        }
        let new_default = metadata.has_default_value().then(|| metadata.default_value().clone());
        self.metadata.override_metadata(self.name(), type_, metadata);
        let mut single = self.single_default_value.borrow_mut();
        if let Some(new_default) = new_default {
            if single.as_ref() != Some(&new_default) {
                *single = None;
            }
        }
    }

    /// Removes the metadata registered for the specified type.
    pub fn unregister(&self, type_: &'static TypeInfo) {
        self.metadata.unregister(type_);
    }

    /// Interprets a typed payload or the cold marker / notification /
    /// conversion cases of an untyped binding. Exact T keeps first precedence.
    pub(crate) fn from_untyped(&self, value: &dyn Any) -> BindingValue<T> {
        if let Some(v) = value.downcast_ref::<T>() {
            BindingValue::new(v.clone())
        } else if let Some(v) = value.downcast_ref::<BindingValue<T>>() {
            v.clone()
        } else {
            let mut typed = None;
            let (kind, error) = resolve_untyped_binding(&self.base, value, &mut |value| {
                typed = value.downcast_ref::<T>().cloned();
                typed.is_some()
            });
            BindingValue::from_notification_parts(kind, typed, error)
        }
    }
}

// BindingValue<T>'s custom Clone remains in the typed caller. The marker and
// conversion policies are common, with the existing notification snapshot
// scope retained around the payload copy.
#[inline(never)]
fn resolve_untyped_binding(
    property: &FerroProperty,
    value: &dyn Any,
    copy_value: &mut dyn FnMut(&dyn Any) -> bool,
) -> (BindingValueType, Option<BindingError>) {
    if value.is::<UnsetValueType>() {
        return (BindingValueType::UNSET_VALUE, None);
    }
    if value.is::<DoNothingType>() {
        return (BindingValueType::DO_NOTHING, None);
    }
    if let Some(notification) = value.downcast_ref::<BindingNotification>() {
        return notification.resolve_binding_value(property.property_type_name(), copy_value);
    }
    if copy_converted_property_value(property, value, copy_value) {
        (BindingValueType::VALUE, None)
    } else {
        (BindingValueType::BINDING_ERROR, Some(BindingError::message(property.invalid_value_message())))
    }
}

impl<T: PropertyValue> PropertyRoutes for StyledProperty<T> {
    fn create_effective_value(&'static self, o: &FerroObject) -> Rc<dyn EffectiveValueDyn> {
        let this = self;
        o.values().create_effective_value(o, this)
    }

    fn route_clear_value(&'static self, o: &FerroObject) {
        o.clear_value(self);
    }

    fn route_coerce_default_value(&'static self, o: &FerroObject) {
        o.values().coerce_default_value(o, self);
    }

    fn route_get_value(&'static self, o: &FerroObject) -> BoxedValue {
        Rc::new(o.get_value(self))
    }

    fn route_get_base_value(&'static self, o: &FerroObject) -> BoxedValue {
        match o.get_base_value(self) {
            Some(v) => Rc::new(v),
            None => FerroProperty::unset_value(),
        }
    }

    fn route_get_default_value(&'static self, type_: &'static TypeInfo) -> BoxedValue {
        Rc::new(self.get_default_value(type_))
    }

    fn route_set_value(
        &'static self,
        o: &FerroObject,
        value: &dyn Any,
        priority: BindingPriority,
    ) -> Option<Rc<dyn IDisposable>> {
        let this = self;
        if value.is::<UnsetValueType>() {
            if priority == BindingPriority::LocalValue {
                o.clear_value(this);
            }
            None
        } else if value.is::<DoNothingType>() {
            None
        } else if let Some(v) = value.downcast_ref::<T>() {
            o.set_value_with_priority(this, v.clone(), priority)
        } else if let Some(v) = convert_property_value::<T>(self, value) {
            o.set_value_with_priority(this, v, priority)
        } else {
            self.invalid_value_type();
        }
    }

    fn route_set_current_value(&'static self, o: &FerroObject, value: &dyn Any) {
        let this = self;
        if value.is::<UnsetValueType>() {
            o.clear_value(this);
        } else if value.is::<DoNothingType>() {
        } else if let Some(v) = value.downcast_ref::<T>() {
            o.set_current_value(this, v.clone());
        } else if let Some(v) = convert_property_value::<T>(self, value) {
            o.set_current_value(this, v);
        } else {
            self.invalid_value_type();
        }
    }

    fn route_set_direct_value_unchecked(&'static self, _o: &FerroObject, _entry: &dyn IValueEntry) {
        panic!("not supported for styled properties");
    }

    fn route_bind(
        &'static self,
        o: &FerroObject,
        source: Rc<dyn IObservable<BoxedValue>>,
        priority: BindingPriority,
    ) -> Rc<dyn IDisposable> {
        o.bind_untyped(self, source, priority)
    }

    fn route_get_metadata(&'static self, type_: &'static TypeInfo) -> FerroPropertyMetadata {
        let metadata = self.get_metadata(type_);
        let base: &FerroPropertyMetadata = &metadata;
        base.clone()
    }

    fn route_unregister(&'static self, type_: &'static TypeInfo) {
        self.unregister(type_)
    }

    fn route_is_valid_value(&'static self, value: &dyn Any) -> bool {
        match value.downcast_ref::<T>() {
            Some(v) => self.is_valid(v),
            None => false,
        }
    }

    fn as_any(&'static self) -> &'static dyn Any {
        self
    }

    fn route_copy_value(&'static self, value: &dyn Any, out: &mut dyn Any) -> bool {
        match (value.downcast_ref::<T>(), out.downcast_mut::<Option<T>>()) {
            (Some(value), Some(out)) => {
                *out = Some(value.clone());
                true
            }
            _ => false,
        }
    }

    fn route_box_value(&'static self, value: &dyn Any) -> Option<BoxedValue> {
        value.downcast_ref::<T>().map(|value| Rc::new(value.clone()) as BoxedValue)
    }

    fn route_create_boxed_local_binding(
        &'static self,
        owner: &FerroObject,
    ) -> Rc<dyn crate::property_store::BoxedLocalBindingValue> {
        crate::property_store::BoxedLocalValueBindingObserver::new(owner, self)
    }

    fn route_create_binding_entry(
        &'static self,
        o: &FerroObject,
        frame: std::rc::Weak<dyn crate::property_store::ValueFrame>,
        source: Rc<dyn IObservable<BoxedValue>>,
    ) -> Rc<dyn crate::property_store::BoxedBindingValue> {
        crate::property_store::create_boxed_binding_entry(o, frame, self, source)
    }
}

impl<T: PropertyValue> StyledProperty<T> {
}

/// An attached property: a styled property that is defined by one class and
/// set on objects of another.
pub struct AttachedProperty<T: PropertyValue> {
    base: StyledProperty<T>,
}

impl<T: PropertyValue> Deref for AttachedProperty<T> {
    type Target = StyledProperty<T>;
    #[inline]
    fn deref(&self) -> &StyledProperty<T> {
        &self.base
    }
}

impl<T: PropertyValue> AttachedProperty<T> {
    pub(crate) fn create(
        name: &str,
        owner_type: &'static TypeInfo,
        host_type: &'static TypeInfo,
        metadata: StyledPropertyMetadata<T>,
        inherits: bool,
        validate: Option<Box<dyn Fn(&T) -> bool>>,
        notifying: Option<NotifyingCallback>,
    ) -> &'static Self {
        let property: &'static Self = Box::leak(Box::new(Self {
            base: StyledProperty::new(name, owner_type, host_type, metadata, inherits, validate, notifying, true),
        }));
        property.base.base.set_routes(&property.base);
        property
    }

    /// Attaches the property as a non-attached property on class `TOwner`.
    pub fn add_owner<TOwner: ObjectType>(&'static self) -> &'static Self {
        FerroPropertyRegistry::instance().register(TOwner::TYPE, &self.base);
        self
    }

    /// Attaches the property as a non-attached property on class `TOwner`,
    /// with metadata for that class.
    pub fn add_owner_with<TOwner: ObjectType>(&'static self, metadata: StyledPropertyMetadata<T>) -> &'static Self {
        FerroPropertyRegistry::instance().register(TOwner::TYPE, &self.base);
        self.base.override_metadata::<TOwner>(metadata);
        self
    }
}

//! Port of the upstream property registry tests.

use super::*;
use crate::*;

test_class!(Class1: FerroObject);

impl Class1 {
    ferro_property!(pub fn foo_property() -> StyledProperty<String> {
        FerroProperty::register::<Class1, _>("Foo", String::new())
    });

    ferro_property!(pub fn baz_property() -> StyledProperty<String> {
        FerroProperty::register::<Class1, _>("Baz", String::new())
    });

    ferro_property!(pub fn qux_property() -> StyledProperty<i32> {
        FerroProperty::register::<Class1, _>("Qux", 0)
    });
}

test_class!(Class2: Class1);

impl Class2 {
    ferro_property!(pub fn bar_property() -> StyledProperty<String> {
        FerroProperty::register::<Class2, _>("Bar", String::new())
    });

    ferro_property!(pub fn flob_property() -> StyledProperty<f64> {
        FerroProperty::register::<Class2, _>("Flob", 0.0)
    });

    ferro_property!(pub fn fred_property() -> StyledProperty<Option<f64>> {
        FerroProperty::register::<Class2, _>("Fred", None)
    });
}

test_class!(Class3: Class1);

impl Class3 {
    ferro_property!(pub fn attached_property() -> AttachedProperty<String> {
        AttachedOwner::attached_property().add_owner::<Class3>()
    });
}

test_class!(AttachedOwner: Class1);

impl AttachedOwner {
    ferro_property!(pub fn attached_property() -> AttachedProperty<String> {
        FerroProperty::register_attached::<AttachedOwner, Class1, _>("Attached", String::new())
    });
}

test_class!(AttachedOwner2: AttachedOwner);
test_class!(Class4: FerroObject);

/// Ensures properties are registered: the equivalent of the static field
/// initialisers of the test classes, in declaration order.
fn setup() {
    let _ = (Class1::foo_property(), Class1::baz_property(), Class1::qux_property());
    let _ = (Class2::bar_property(), Class2::flob_property(), Class2::fred_property());
    let _ = AttachedOwner::attached_property();
    let _ = Class3::attached_property();
}

fn names(properties: &[&'static FerroProperty]) -> Vec<&'static str> {
    properties.iter().map(|p| p.name()).collect()
}

#[test]
fn registered_properties_count_reflects_newly_added_attached_property() {
    setup();
    let registry = FerroPropertyRegistry::default();
    let metadata = StyledPropertyMetadata::new(Some(0));
    let property =
        AttachedProperty::<i32>::create("test", FerroObject::TYPE, FerroObject::TYPE, metadata, true, None, None);
    property.set_inherited_value_changed(Some(crate::property_store::EffectiveValue::<i32>::notify_inherited_value_changed));
    registry.register(FerroObject::TYPE, property);
    registry.register_attached(Class4::TYPE, property);
    property.add_owner::<Class4>();

    assert_eq!(1, registry.properties().len());
}

#[test]
fn get_registered_returns_registered_properties() {
    setup();
    let registered = FerroPropertyRegistry::instance().get_registered(Class1::TYPE);

    assert_eq!(vec!["Foo", "Baz", "Qux"], names(&registered));
}

#[test]
fn get_registered_returns_registered_properties_for_base_types() {
    setup();
    let registered = FerroPropertyRegistry::instance().get_registered(Class2::TYPE);

    assert_eq!(vec!["Bar", "Flob", "Fred", "Foo", "Baz", "Qux"], names(&registered));
}

#[test]
fn get_registered_attached_returns_registered_properties() {
    setup();
    let registered = FerroPropertyRegistry::instance().get_registered_attached(Class1::TYPE);

    assert!(names(&registered).contains(&"Attached"));
}

#[test]
fn get_registered_attached_returns_registered_properties_for_base_types() {
    setup();
    let registered = FerroPropertyRegistry::instance().get_registered_attached(Class2::TYPE);

    assert!(names(&registered).contains(&"Attached"));
}

#[test]
fn find_registered_finds_property() {
    setup();
    let result = FerroPropertyRegistry::instance().find_registered(Class1::TYPE, "Foo");

    assert_eq!(Some(Class1::foo_property().as_property()), result);
}

#[test]
fn find_registered_doesnt_find_nonregistered_property() {
    setup();
    let result = FerroPropertyRegistry::instance().find_registered(Class1::TYPE, "Bar");

    assert!(result.is_none());
}

#[test]
fn find_registered_finds_unqualified_attached_property_on_registering_type() {
    setup();
    let result = FerroPropertyRegistry::instance().find_registered(AttachedOwner::TYPE, "Attached");

    assert!(std::ptr::eq(AttachedOwner::attached_property().as_property(), result.expect("found")));
}

#[test]
fn find_registered_finds_add_ownered_attached_property() {
    setup();
    let result = FerroPropertyRegistry::instance().find_registered(Class3::TYPE, "Attached");

    assert!(std::ptr::eq(AttachedOwner::attached_property().as_property(), result.expect("found")));
}

#[test]
fn find_registered_doesnt_find_non_add_ownered_attached_property() {
    setup();
    let result = FerroPropertyRegistry::instance().find_registered(Class2::TYPE, "Attached");

    assert!(result.is_none());
}

test_class!(UnregisterBase: FerroObject);

impl UnregisterBase {
    ferro_property!(pub fn foo_property() -> StyledProperty<String> {
        FerroProperty::register::<UnregisterBase, _>("Foo", String::from("foodefault"))
    });
}

test_class!(UnregisterDerived: UnregisterBase);
test_class!(UnregisterDerived2: UnregisterBase);

/// Not from upstream, which has no test of `UnregisterByModule`: the
/// metadata a type overrides is gone once the type is unregistered.
#[test]
fn unregister_by_module_removes_metadata_of_types() {
    let property = UnregisterBase::foo_property();
    property.override_default_value_for(UnregisterDerived::TYPE, String::from("foooverride"));

    assert_eq!("foooverride", property.get_default_value(UnregisterDerived::TYPE));
    assert_eq!("foodefault", property.get_default_value(UnregisterBase::TYPE));

    assert!(FerroPropertyRegistry::instance().unregister_by_module([UnregisterDerived::TYPE]));

    assert_eq!("foodefault", property.get_default_value(UnregisterDerived::TYPE));
    assert_eq!("foodefault", property.get_default_value(UnregisterBase::TYPE));
}

/// Not from upstream: `FerroProperty::unregister` removes the metadata of a
/// type through the untyped property.
#[test]
fn unregister_removes_metadata_of_type() {
    let property = UnregisterBase::foo_property();
    property.override_default_value_for(UnregisterDerived2::TYPE, String::from("foooverride"));
    assert_eq!("foooverride", property.get_default_value(UnregisterDerived2::TYPE));

    property.as_property().unregister(UnregisterDerived2::TYPE);

    assert_eq!("foodefault", property.get_default_value(UnregisterDerived2::TYPE));
}
